export const CLASSIC_BATTLE_BRIEFINGS: Readonly<Record<string, ClassicBattleBriefing>> = {
    "aiji_lameisisi": {"strategic":["公元前十三世纪初，埃及新王国与安纳托利亚高原的赫梯帝国并立为近东两大强权，双方围绕叙利亚与黎凡特走廊争战不休。奥龙特斯河谷的重镇卡迭石扼守南北驿道与内陆商路，阿穆鲁等附庸邦国在两强之间反复易帜。","年轻气盛的埃及法老拉美西斯继位后经略迦南，迫使阿穆鲁重归埃及，决意北上夺回先王得而复失的卡迭石，重振北方疆界。为此埃及倾动国力，编成阿蒙、拉、普塔赫、塞特各路军团，由拉美西斯亲统北出；","赫梯王穆瓦塔利亦纠合小亚细亚与叙利亚诸附庸之师南下迎敌，两大帝国主力正向奥龙特斯河谷步步逼近。"],"tactical":["卡迭石城筑于奥龙特斯河西岸台地，河水与支流环绕其侧。拉美西斯误信赫梯细作称敌军尚在远方，遂率阿蒙军团先行涉过浅滩，于城西北单独扎营，与后方行进中的拉、普塔赫诸军团拉开了间距。","岂料穆瓦塔利早已将主力隐蔽于卡迭石城东，趁埃及行军队列脱节之际，遣精锐战车悄然渡河，拦腰冲垮拉军团，旋即扑向阿蒙大营。营内惊溃之际，拉美西斯陷于重围，亲率近卫乘战车反复冲杀苦撑待援。","危急关头，自海岸赶来的埃及支队抵达战场外围，突击忙于劫营的赫梯车队，普塔赫军团亦自南面赶到接应，将赫梯战车逼回河中。此战两军伤亡俱重，拉美西斯无力攻城而引军南还，卡迭石仍归赫梯控制，十余年后两国终缔和约。"],"history":"公元前一二七四年五月，埃及新王国法老拉美西斯北征叙利亚，与赫梯王穆瓦塔利于奥龙特斯河畔的卡迭石会战。埃及军分阿蒙、拉、普塔赫、塞特诸军团北进，拉美西斯轻信诈降牧人，率阿蒙军团孤军渡河扎营，遭赫梯战车渡河奇袭，拉军团溃散、法老被围。幸赖海岸支队奈阿林援军与普塔赫军团赶到解围，次日再战不分胜负，卡迭石仍属赫梯，十余年后双方缔结银板和约。","sources":"卡迭石铭文；埃赫银板和约"},
    "ailan_julushi": {"strategic":["公元前六世纪中叶，兴起于波斯高原的居鲁士二世先后推翻米底宗主、并吞富庶的吕底亚王国，构建起横跨伊朗与小亚细亚的阿契美尼德波斯帝国，西亚唯剩新巴比伦尚存一隅。","此时巴比伦国内却陷入深重裂痕，国王那波尼德长年避居阿拉伯绿洲泰马，留王子伯沙撒在都城摄政，更因独尊月神辛而冷落巴比伦主神马尔杜克，招致权倾朝野的马尔杜克祭司集团与都城臣民普遍怨恨。","公元前五三九年，居鲁士二世看准巴比伦人心离散之机，统率波斯大军西渡底格里斯河，在奥皮斯一举击溃巴比伦野战主力，顺势收降北门重镇西帕尔，旋即挥师南指号称固若金汤的巴比伦都城。"],"tactical":["巴比伦城拥有举世闻名的内外双重巨垣，幼发拉底河自北向南穿城而过，河口设有铜栅水门；留守都城的伯沙撒自恃城高粮足，对城外波斯大军并不以为意，在城中照常欢庆节日。","居鲁士二世审视水势，深知强攻巨垣必致旷日持久，遂采纳奇策，命工兵在巴比伦上游掘开旧有泄洪渠与低洼泽地，趁夜分流幼发拉底河水。河道水位骤降至齐腰深浅，预先埋伏于南北入城水口两侧的波斯精锐顺着干浅河床悄然涉水潜入城中；","恰逢城内守卫因节庆松懈、沿河铜门未曾紧闭，波斯士卒一举突入内城控制王宫，伯沙撒在乱军中丧命。天明之后巴比伦全城归降，居鲁士二世严禁劫掠，尊崇马尔杜克神庙并下诏释放被掳各族归乡，新巴比伦帝国就此并入波斯版图。"],"history":"公元前五三九年秋，阿契美尼德波斯国王居鲁士二世大举进攻新巴比伦帝国，先于底格里斯河畔奥皮斯大破巴比伦军，十月进抵巴比伦城。据那波尼德编年史，波斯军未经大规模攻城即入城擒王；希罗多德与但以理书则载留守摄政太子伯沙撒恃坚城宴饮无备，波斯军导引幼发拉底河水入泽，涉浅河床奇袭入城，伯沙撒死，新巴比伦灭亡。","sources":"那波尼德编年史；居鲁士圆柱；希罗多德·历史；但以理书"},
    "ailan_julushi@-547": {"strategic":["公元前六世纪中叶，居鲁士二世推翻米底帝国后，与米底王室世代联姻的小亚细亚霸主吕底亚国王克罗伊索斯大为惊恐，急忙缔结埃及、巴比伦与斯巴达四国同盟，抢先渡过哈里斯河东侵波斯领地。两军在卡帕多细亚的普特里亚血战难分高下；","时值寒冬降临，克罗伊索斯按常理断定波斯军绝不敢顶风冒雪深入小亚细亚，便放心退回都城撒狄，一面暂行遣散麾下雇佣盟军，一面传信盟国约定次年开春会师大举伐波斯。","岂料居鲁士二世一眼看穿对手麻痹心理，作出惊人决断，不等春暖便率波斯远征军踏雪西进，昼夜疾行直逼撒狄城郊的提姆布拉平原，逼迫尚未等来盟友的克罗伊索斯仓促出城背水一战。"],"tactical":["提姆布拉平原地势辽阔平坦，正是吕底亚引以为傲的长矛重骑驰骋冲杀的绝佳猎场，克罗伊索斯尽起本国精锐骑队与埃及重装方阵，拉出宽大两翼企图将孤军远来的波斯军四面合围。","居鲁士二世采纳米底名将哈尔帕古斯献策，将波斯步卒与弓箭塔车收拢成纵深严密的空心大阵，更把随军驮运粮草的骆驼尽数卸下辎重，由骑手乘骑排在最前线迎向吕底亚铁骑。","交锋伊始，吕底亚两翼骑队呼啸夹击而来，不料战马从未见过骆驼形貌、更极度畏惧骆驼气味，临近阵前纷纷惊嘶乱窜、调头狂奔，骑士被迫下马步战而阵形大乱。居鲁士二世趁势令两翼波斯车骑与弓手全力反扑，将失却骑兵掩护的吕底亚军分割击溃；","克罗伊索斯败逃退入撒狄城中，半月后城破被俘，富甲天下的吕底亚自此并入波斯帝国。"],"history":"公元前五四七年冬，小亚细亚强国吕底亚国王克罗伊索斯在普特里亚与居鲁士二世激战不分胜负后，以为寒冬将至波斯必不进兵，遂回都撒狄遣散盟军待春再战。居鲁士二世出其不意冒冬疾追至撒狄城东的提姆布拉平原，以辎重骆驼列于前阵惊散吕底亚精锐骑兵，合围大破克罗伊索斯主力，随即攻陷撒狄灭亡吕底亚。异说：年份一作前五四六年。","sources":"希罗多德·历史·第一卷；色诺芬·居鲁士的教育·第七卷"},
    "ailan_julushi@-550": {"strategic":["公元前六世纪中叶，统治伊朗高原与北两河的米底帝国表面强盛，内部却因国王阿斯提阿格斯严苛专断而贵族离心。居鲁士二世继任南方附庸波斯诸部之长后，暗中联络对阿斯提阿格斯心怀怨恨的米底重臣哈尔帕古斯，团结波斯各部落公然举起反抗米底宗主的旗帜。","阿斯提阿格斯闻变震怒，先行派出的讨伐军竟在阵前部分倒戈投向波斯；米底老王遂征发帝国本部全部兵马，御驾亲征南下波斯本土，誓要将叛乱彻底扑灭。","面对兵力远胜己方的宗主大军，居鲁士二世一面将波斯老弱妇孺转移至帕萨尔加德山岭，一面率波斯将士依托群山隘口节节阻击，双方最终在帕萨尔加德高原迎来了决定高原易主的生死决战。"],"tactical":["帕萨尔加德四周群山环抱，谷口险峻，居鲁士二世将波斯主力部署在通往家属营地的山坡防线上。阿斯提阿格斯抵达后分遣精兵绕行攀上两侧高山，与正面主力夹击波斯防线；首日激战波斯军寡不敌众，被迫向后方山顶退却。","退至山巅之际，波斯妇女纷纷迎面跑出营帐，高声斥责退缩士卒莫非想逃回母腹避死，波斯将士羞愤交加，士气陡然暴涨。次日清晨，居鲁士二世亲率全军自山顶怒吼俯冲而下，迎头猛撞正在仰攻登山的米底大军；","米底军阵在陡坡上阵脚大乱，兼之军中早怀异志的贵族部队临阵哗变倒戈，米底战线瞬间土崩瓦解。居鲁士二世一鼓作气攻破米底王营，生擒阿斯提阿格斯并善待不杀，随后进占米底都城埃克巴坦那，阿契美尼德波斯帝国由此崛起于世。"],"history":"公元前五五〇年，波斯安善国王居鲁士二世起兵反抗宗主米底帝国，经边境交锋后退守波斯腹地帕萨尔加德群山。米底末王阿斯提阿格斯亲率大军围攻，首日迫使波斯军退保山顶；次日波斯军在妇孺激励下拼死反扑，加之部分米底贵族倒戈，居鲁士二世大破米底主力并生擒阿斯提阿格斯，取代米底建立阿契美尼德波斯帝国。","sources":"那波尼德编年史；希罗多德·历史·第一卷；尼古拉乌斯残篇"},
    "ailan_shuteluke": {"strategic":["公元前十二世纪中叶，统治巴比伦尼亚累世已久的加喜特王朝陷入内忧外患，北方亚述频频蚕食其边地，国内王位更迭动荡，国势日渐凋敝。与此同时，雄踞伊朗高原西南麓的埃兰王国在纳克昆特治下重振声威，国库充盈，兵甲强盛。","埃兰王室早年曾与加喜特王室累代联姻，纳克昆特自认拥有巴比伦王位的继承资格，遂遣使向巴比伦索讨王位，却遭巴比伦贵族严词拒绝。","纳克昆特以此为名兴师问罪，率埃兰大军自苏萨西出，强渡底格里斯河，接连攻陷埃什嫩那、西帕尔与基什等重镇，征收重贡，最终将兵锋推至巴比伦内城之下，加喜特王朝的存亡悬于一线。"],"tactical":["巴比伦城跨幼发拉底河而筑，重垣深壕拱卫着内城神庙与王宫，加喜特守军在恩利尔纳丁统率下退保内城，企图凭坚城消耗远道而来的埃兰师旅。纳克昆特此前已扫清外围卫城，切断了巴比伦上下游的水陆粮援，随即督率埃兰步骑与攻城器械四面合围，昼夜猛攻内城城垣。","守军久困孤城，外无邻邦来救，内乏粮秣接济，城防终被埃兰军强行突破。埃兰大军涌入巴比伦内城大肆搜掠，不仅俘获抵抗的巴比伦王室，更将西帕尔与巴比伦庙宇中珍藏的汉谟拉比法典石碑、纳拉姆辛纪功碑乃至主神马尔杜克神像尽数拆运回都城苏萨。","绵延数代的加喜特王朝至此覆灭，埃兰威名一时震动两河。"],"history":"公元前十二世纪中叶，埃兰舒特鲁克王朝国王纳克昆特乘巴比伦加喜特王朝衰弱及亚述侵逼之机大举西征，于公元前一一五八年攻破巴比伦诸城，掳走汉谟拉比法典石碑与纳拉姆辛胜利碑运回苏萨；其后加喜特末王恩利尔纳丁继续抵抗，终在公元前一一五五年前后兵败被俘，马尔杜克神像被掳，统治巴比伦数世纪的加喜特王朝覆灭。注：任务表敌方势力标为迦勒底，实为加喜特王朝。","sources":"苏萨埃兰王铭；巴比伦同步史"},
    "aqimeinide_daliushi": {"strategic":["公元前五二二年，波斯王冈比西斯二世自埃及班师途中暴毙，波斯宫廷围绕高墨达夺权爆发剧变；大流士一世联合波斯贵族诛杀高墨达夺取王位，然而帝国根基未稳，埃兰、米底、亚述等行省趁乱相继揭竿而起。","在富庶的巴比伦尼亚，贵族出身的尼丁图-贝尔看准波斯中枢无暇四顾，公然宣称自己是巴比伦末代国王那波尼德之子，袭用尼布甲尼撒名号在巴比伦登基称王。怀念故国的巴比伦民众与西帕尔、乌鲁克诸城纷纷景从，两河腹地转瞬脱离波斯管辖。","大流士一世深知巴比伦乃帝国赋税命脉，一旦坐视其复国，东方诸叛更难弹压，遂亲率波斯与米底劲旅火速西征，直扑尼丁图-贝尔扼守的两河防线。"],"tactical":["巴比伦外有底格里斯与幼发拉底两河环护，内有高城深池可恃。尼丁图-贝尔先派兵携战船沿底格里斯河西岸布防，断绝渡口舟楫；","大流士一世不为所阻，命波斯士卒乘皮筏与骆驼战马强行涉水突击，一举冲垮河岸防线，继而又在幼发拉底河畔的扎扎那迎头痛击尼丁图-贝尔亲率的主力，将巴比伦野战部队赶入河中击溃。尼丁图-贝尔仅携亲随逃回巴比伦城闭门死守，企图倚仗坚固城垣与充足积粮持久相抗。","大流士一世乘胜合围巴比伦，封锁水陆要道，督军分道猛攻城防要害，迅速突入城内平息巷战，生擒尼丁图-贝尔并将其处死示众。巴比伦复国之梦旋起旋灭，大流士一世稳住两河大局，进而逐一荡平帝国全境叛乱。"],"history":"波斯王冈比西斯二世死后帝国大乱，大流士一世夺位之际各省纷叛，巴比伦贵族尼丁图-贝尔自称前王那波尼德之子尼布甲尼撒三世自立为王。大流士一世亲统大军强渡底格里斯河，再败叛军于幼发拉底河畔扎扎那，追击合围巴比伦城并破城擒杀尼丁图-贝尔。异说：贝希斯敦铭文系尼丁图-贝尔败亡于前五二二年末，前五二一年再叛者为阿拉卡，希罗多德则杂糅长围故事。","sources":"贝希斯敦铭文；希罗多德·历史·第三卷"},
    "bfe2_esarhaddon": {"strategic":["公元前六七一年，距离亚述首次征埃受挫已过两载，推罗王再度倚仗法老塔哈尔卡的撑腰公然背叛亚述，黎凡特局势再起波澜。亚述王以撒哈顿痛定思痛，决心集举国之力彻底折服埃及。","这一次他不再贪图急行突袭，而是事先征调阿拉伯游牧部族的骆驼驼运皮囊饮水，分兵钳制推罗海岛，亲统规模远超前役的亚述大军自阿什凯隆稳步南下，从容越过西奈荒漠。","亚述大军踏入埃及东境后稳扎稳打，连续击破塔哈尔卡派出的拦截兵马，沿着尼罗河三角洲边缘节节推进，兵锋直抵上下埃及交界的古都孟菲斯城下。"],"tactical":["孟菲斯扼守尼罗河三角洲顶点，白墙高耸，水陆辐辏，乃是统御下埃及的枢纽重镇；塔哈尔卡亲在城内外督师布防，企图背城决一死战。以撒哈顿率亚述劲旅进抵城郊，先在城外野战中击溃埃军出击部队，将塔哈尔卡本人射伤，迫使守军退缩入城，随即水陆并进合围孟菲斯。","亚述工兵娴熟架设攻城云梯与冲车，在密集箭雨掩护下昼夜不停猛攻城垣，仅用半日强攻便突破外郭防线杀入城中。塔哈尔卡见城池难保，只得乘乱弃城，沿尼罗河南逃上埃及底比斯；","亚述军攻占孟菲斯，尽俘塔哈尔卡的王后、王子与王室眷属，收缴无数金银神像，并在下埃及分封诸侯、派驻总督，亚述帝国的疆域至此臻于极盛。"],"history":"公元前六七一年夏，亚述王以撒哈顿吸取前败教训，备足骆驼饮水稳步穿越西奈，连战击破埃及边防，直抵下埃及重镇孟菲斯。法老塔哈尔卡力战不支，负伤弃城南逃底比斯，以撒哈顿攻破孟菲斯，俘获塔哈尔卡王后、太子及宫廷贵族，册封尼科一世等三角洲诸侯，将下埃及纳入亚述版图。","sources":"以撒哈顿辛吉尔利胜利碑；巴比伦编年史"},
    "bfe2_esarhaddon@-673": {"strategic":["公元前七世纪前期，亚述王以撒哈顿平定父王遇刺后的内乱，重新确立对巴比伦与叙利亚的威权，唯独西南方向的埃及第二十五王朝始终是帝国心腹大患。法老塔哈尔卡坐拥尼罗河与库施之富，频频向西顿、阿什凯隆等沿海藩属输送财货与援军，煽动黎凡特诸邦反抗亚述征敛。","以撒哈顿踏平西顿之后，认定唯有直捣尼罗河三角洲方能永绝西顾之忧；公元前六七三年初春，以撒哈顿在阿什凯隆集结亚述劲旅，决意出奇制胜，催动大军以罕见的急行军速度强穿寸草不生的西奈沙碛，企图在塔哈尔卡完成全国动员之前一举夺下埃及东门佩鲁西姆。"],"tactical":["佩鲁西姆横亘于西奈荒原尽头与尼罗河最东支流之间，遍布盐碱沼泽、流沙与人工河渠。以撒哈顿因求胜心切，督促亚述重兵在缺乏足够驼运水源的条件下连日强行跋涉，待前锋望见佩鲁西姆防线时，全军已是人困马乏、队列拉长。","岂料塔哈尔卡早已在东境高筑营垒、疏浚水网严阵待敌，趁亚述军立足未稳、战车与重步卒陷于沙泽泥泞之际，挥动养精蓄锐的埃及与库施主力迎面发起猛攻。亚述将士虽奋力死战，怎奈久行力竭、水粮不继，在熟悉地形的埃军轮番冲击下伤亡惨重。","以撒哈顿见奇袭已失先机，若再恋战恐致全军覆没于荒漠，当机立断下令收拢残师北撤，把灭埃之志留待两载之后的再度南征。"],"history":"公元前六七三年初春，新亚述国王以撒哈顿为铲除黎凡特各叛乱城邦的幕后支柱埃及，亲率远征军自巴勒斯坦南端强行急行军穿越西奈荒漠，进攻埃及东境门户佩鲁西姆一带。因行军过急、沙漠缺水疲敝，亚述军在埃及东境遭法老塔哈尔卡以逸待劳迎头痛击而大败，以撒哈顿被迫撤军返国整顿。异说：巴比伦编年史或推算为前六七四年三月。","sources":"巴比伦编年史；亚述年代记"},
    "dibisi_tahaerka": {"strategic":["公元前七世纪上半叶，新亚述帝国已囊括两河流域与叙利亚巴勒斯坦大部，唯独尼罗河流域在库施王室建立的第二十五王朝统辖下重归统一，成为近东唯一能与亚述抗衡的大国。","法老塔哈尔卡即位后锐意恢复古埃及荣光，不断暗中资助腓尼基与非利士诸城抗拒亚述统治，令亚述西疆叛乱屡扑屡起。亚述王以撒哈顿荡平西顿等城后，决意直捣根源、一举征服埃及。","公元前六七三年，以撒哈顿集结远征军团，自巴勒斯坦南端强行穿越干旱荒凉的西奈沙碛，企图以雷霆疾行抢占尼罗河三角洲东门户佩鲁西姆；塔哈尔卡早获边报，立即调集埃及与库施精锐北上东境迎敌。"],"tactical":["佩鲁西姆地处西奈沙漠与尼罗河三角洲东端水网的交界要冲，沙丘、盐泽与河汊犬牙交错，大军机动极为不易。以撒哈顿催督亚述远征军昼夜急行，穿越缺水少粮的西奈荒原，士卒抵达埃及东境防线时已是饥渴交迫、阵形疲散。","反观塔哈尔卡早已依托三角洲东翼的水道与边塞壁垒严阵以待，粮秣充足，士气正盛。待亚述前锋踏入湿软河网与沙丘地带、攻势受阻之际，塔哈尔卡果断挥师全线出击，埃及与库施弓步队伍凭熟习地形之利猛烈反扑。","疲敝不堪的亚述军首尾难顾，在激战中遭受重创，后方补给线亦面临断绝之虞；以撒哈顿只得下令放弃进攻，率残部狼狈北撤回返亚述，塔哈尔卡成功保住了埃及本土的独立。"],"history":"公元前六七三年初春，亚述王以撒哈顿为断绝黎凡特叛乱外援，率军疾行远征埃及东境门户佩鲁西姆与西奈走廊一带。埃及第二十五王朝即库施王朝法老塔哈尔卡预作整备，乘亚述军长途奔袭疲敝之际迎头痛击，大败亚述军，迫使以撒哈顿撤回尼尼微。异说：巴比伦编年史或折算为前六七四年三月，亚述官方铭文隐讳此败。","sources":"巴比伦编年史；以撒哈顿王家铭文"},
    "dibisi_tahaerka@-671": {"strategic":["公元前六七一年，埃及法老塔哈尔卡在东境击退亚述首次入侵已有两载，尼罗河两岸重修神庙、民生渐复，塔哈尔卡亦继续联结腓尼基重镇推罗共御亚述。","然而亚述王以撒哈顿决不甘心前番受挫，暗中集结起远胜往昔的倾国重兵，更重金收买西奈半岛的阿拉伯游牧部族提供庞大骆驼水队，一举克服了横亘两军之间的沙漠缺水天险。亚述大军避开推罗坚城分兵监视，主力以雷霆之势突破埃及东门防线，沿三角洲东缘连战疾进；","塔哈尔卡急调上下埃及与库施精兵会聚古都孟菲斯，决心依托尼罗河枢纽坚城挡住以撒哈顿的灭国兵锋。"],"tactical":["孟菲斯控扼上下埃及咽喉，高大白墙外环绕着尼罗河干流与深阔壕沟，塔哈尔卡亲自披挂坐镇，先遣精兵出城迎击以挫亚述前锋锐气。然而亚述大军有备而来，铁甲步骑与强弓硬弩层层推进，城外野战异常惨烈，塔哈尔卡在阵前督战时数度中箭负伤，埃及出击部队被迫退回城垣之内闭门固守。","以撒哈顿旋即水陆合围孟菲斯，驱使工兵顶着城头滚木礌石架起攻城冲车与云梯，昼夜轮番猛扑外郭薄弱地段。经过浴血巷战，外城防线被亚述重步卒强行撕裂，塔哈尔卡见孤城难支，为保住复国火种只得含恨突围，沿尼罗河南撤退保底比斯与库施本土；","孟菲斯虽告失陷、王室家眷被掳，塔哈尔卡却未曾屈服，不久后便再度挥师北上掀起反攻。"],"history":"公元前六七一年夏，亚述王以撒哈顿吸取两年前败退教训，借助阿拉伯驼队供水穿越西奈，连续突破埃及东境防线进逼下埃及都城孟菲斯。埃及第二十五王朝法老塔哈尔卡亲督守军在孟菲斯城内外浴血拒战，终因亚述攻势猛烈、身受箭伤而弃城南退上埃及底比斯，孟菲斯陷落，王后与王子被俘，但塔哈尔卡两年后仍自南方反攻一度收复孟菲斯。","sources":"巴比伦编年史；以撒哈顿辛吉尔利胜利碑"},
    "gen_aristides": {"strategic":["公元前四七九年，波斯舰队虽在前一年萨拉米斯海战中受挫，波斯陆军精锐却依然完整留驻希腊，统帅马尔多尼乌斯先遣使许以优厚条件拉拢雅典单独媾和，企图瓦解希腊同盟。","素以公正著称、刚从流放中召回的雅典将军阿里斯提德主持大局，断然回绝波斯诱降，并敦促迟疑观望的斯巴达尽发伯罗奔尼撒重装方阵北上会师。马尔多尼乌斯见劝降不成，再度焚毁雅典空城，随即主动撤往地势平坦、盟邦底比斯全力接济粮草的彼奥提亚境内。","阿里斯提德率雅典重装步卒与斯巴达及诸城邦联军会合，翻越基泰龙山脉追击而至，与马尔多尼乌斯大军在普拉提亚城郊阿索波斯河两岸列营对峙。"],"tactical":["普拉提亚南依基泰龙山麓，北临阿索波斯河开阔平原，马尔多尼乌斯在河北岸筑起坚固木寨，以波斯本阵对峙右翼斯巴达军，将亲波斯的底比斯方阵摆在对阵左翼阿里斯提德所部雅典军的位置。两军隔河相持十余日，马尔多尼乌斯纵轻骑不断袭扰山隘辎重，更填毁联军赖以饮水的泉眼。","联军断水乏粮，决定乘夜向山根移营，不料各邦队伍夜行脱节，天明时右翼斯巴达与左翼雅典分隔各自为战。马尔多尼乌斯误认希腊联军溃逃，挥动波斯步骑渡河猛扑斯巴达阵地；阿里斯提德急欲驰援，却遭底比斯方阵迎头死死缠住。恶战之中，斯巴达方阵顶住箭雨反冲，阵斩马尔多尼乌斯；","阿里斯提德亦率雅典军正面击溃底比斯劲旅，随即会师攻破波斯木寨，彻底解除希腊本土亡国之危。"],"history":"公元前四七九年八月，萨拉米斯海战后留驻希腊的波斯统帅马尔多尼乌斯再占雅典，退入彼奥提亚平原普拉提亚寻战。斯巴达摄政保萨尼亚斯任希腊联军统帅，阿里斯提德统率雅典公民重装步兵居左翼。波斯骑兵截断联军泉水与粮道迫其夜撤，马尔多尼乌斯误以为联军溃逃率军猛扑，被斯巴达方阵击毙，阿里斯提德击败投靠波斯的底比斯军，合破波斯木寨，彻底终结波斯侵希。","sources":"希罗多德·历史·第九卷；普鲁塔克·阿里斯提德传"},
    "gen_artaphernes": {"strategic":["公元前五世纪初，阿契美尼德波斯帝国早已将小亚细亚西岸的爱奥尼亚希腊诸城邦纳入版图，委派亲波斯的各邦僭主代为管辖，征调赋税与舰船。米利都代理僭主阿里斯塔哥拉斯先前鼓动波斯远征纳克索斯岛惨遭失败，既无力偿还军费，又深恐遭波斯吕底亚总督阿尔塔弗涅斯治罪罢黜；","他遂铤而走险，率先在米利都宣布废除僭主制，煽动爱奥尼亚各城驱逐亲波斯首领起兵反叛。阿里斯塔哥拉斯更渡海前往希腊本土求援，说动雅典与埃雷特里亚派遣战舰东渡助战。","公元前四九八年春，叛军与希腊援军在以弗所集结登陆，沿卡伊斯特河翻越特摩卢斯山脉，出其不意直扑阿尔塔弗涅斯驻节的吕底亚首府撒狄。"],"tactical":["撒狄下城铺展于帕克托卢斯河谷，背靠绝壁高耸、三面险峻难攀的撒狄卫城；波斯吕底亚总督阿尔塔弗涅斯在阿里斯塔哥拉斯一方联军翻山奇袭之时未及防备，下城很快陷落。","阿尔塔弗涅斯临危不乱，果断收拢精锐卫队退入山顶撒狄卫城凭险死守，将贪图战利品的爱奥尼亚与希腊士卒死死挡在绝壁之下。联军久攻卫城不下，混战中下城芦苇屋顶的民居失火引燃，干燥季风助长火势迅速席卷全城，将正欲抢掠的希腊人困于外围火墙与卫城之间。","阿尔塔弗涅斯见敌阵大乱，当即率波斯守军自卫城冲杀而下，与退聚市集的吕底亚军民合力反击。联军闻波斯各省援兵将至，连夜弃城溃退；撒狄神庙被焚彻底激怒波斯王室，自此埋下希波大战的祸根。"],"history":"公元前四九八年春，小亚细亚爱奥尼亚诸希腊城邦在米利都僭主阿里斯塔哥拉斯策动下反叛波斯，联合雅典与埃雷特里亚援军自以弗所翻山突袭波斯吕底亚行省首府撒狄。波斯总督阿尔塔弗涅斯兵力不及，退守撒狄卫城顽强抵抗；下城民居失火焚毁全城，阿尔塔弗涅斯乘烟火突围反击逼退联军，并在波斯援军配合下追败希腊人。","sources":"希罗多德·历史·第五卷"},
    "gen_brasidas": {"strategic":["公元前五世纪后期，雅典与斯巴达在伯罗奔尼撒战争中鏖战近十载，双方各自疲敝，原本曾达成一年休战协定。","然而色雷斯战场的归属令战火重燃，斯巴达杰出将领巴西达斯此前孤军远征北境，以宽厚怀柔结合奇袭夺取了雅典在色雷斯最重要的殖民重镇安菲波利斯，直接扼断雅典造船木材与金银矿税来源。","休战期满后，曾在斯法克特里亚立功的雅典主战派领袖克里昂力主武力收复失地，亲率公民重装方阵与盟军乘舰北上，以河口港城埃昂为基地，连克周边据点并派人征调马其顿与色雷斯援军；巴西达斯则率军进驻城外高地严密监视，继而退入安菲波利斯城内隐蔽待机。"],"tactical":["安菲波利斯三面环绕斯特律蒙河，东面筑有长墙封锁山脊，地势易守难攻。克里昂因麾下厌倦久候援军，便率全军登上城东山脊窥探，见城门紧闭、墙头寂然无备，误以为巴西达斯怯战不出。","实则巴西达斯已从城门缝隙窥见雅典军枪矛晃动、阵脚松散，当即自选敢死锐卒伏于南门，另命副将屯兵北侧栅门准备夹击。恰在此时克里昂侦知城内集结迹象，无意在援军未至前决战，竟下令左翼先行调头撤往埃昂；这一转身致使雅典步卒纷纷将未持盾牌的右侧身体暴露给城门方向。","巴西达斯看准破绽，亲率精锐推开南门疾冲雅典军中段，北门守军亦同步杀出猛扑雅典右翼。雅典军腹背受击大溃，克里昂奔逃途中被标枪刺死，巴西达斯冲阵时亦负重伤，闻捷报后瞑目而逝；两邦主战魁首同日陨命，随即缔结和约。"],"history":"公元前四二二年，伯罗奔尼撒战争第一阶段尾声，雅典主战派领袖克里昂率远征军北上色雷斯，企图夺回被斯巴达名将巴西达斯攻占的战略重镇安菲波利斯。克里昂率军进抵城外山丘侦察，见城内寂静遂转身撤回埃昂待援，暴露无盾右侧翼；巴西达斯与克莱阿里达斯分自两门突击，雅典军大溃、克里昂被杀，巴西达斯亦重伤身亡，促成尼西阿斯和约。","sources":"修昔底德·伯罗奔尼撒战争史·第五卷"},
    "gen_cambyses": {"strategic":["公元前六世纪后期，阿契美尼德波斯帝国已尽揽两河、小亚细亚与叙利亚之地，整个古近东仅剩埃及第二十六王朝孤悬尼罗河畔。居鲁士二世未及征埃便战死东疆，其子冈比西斯二世继位后立即筹划南征。","此际埃及局势急转直下，老法老雅赫摩斯二世原先联络塞浦路斯与萨摩斯海军共同防波斯，不料萨摩斯僭主中途倒戈，熟知埃及军防虚实的希腊雇佣将领法涅斯亦叛逃献策；更雪上加霜的是老法老在开战前夕病逝，缺乏历练的普萨美提克三世仓促登基。","冈比西斯二世借阿拉伯部族驼队供水顺利穿越西奈荒漠，集结腓尼基舰队水陆并进，直扑埃及东境咽喉佩鲁西姆要塞。"],"tactical":["佩鲁西姆要塞扼守尼罗河最东侧入海支流，沼泽与沙堤拱卫城外，普萨美提克三世集结埃及本土军与效忠法老的希腊、卡里亚雇佣队伍驻防要塞外围，企图将波斯军挡在三角洲门户之外。两军在要塞前展开惨烈血战，双方雇佣队殊死肉搏，战况一时难解难分；","但在波斯优势步骑与密集弓矢的轮番冲击下，缺乏实战调度经验的普萨美提克三世渐失章法，埃及防线终被撕开缺口，守军溃退入佩鲁西姆城中。冈比西斯二世随即合围要塞昼夜猛攻，据传波斯军更在阵前驱赶埃及人视为神圣的猫犬等动物扰乱守军心神，终迫使佩鲁西姆陷落。","普萨美提克三世败逃孟菲斯，不久城破被俘，埃及自此沦为波斯帝国行省。"],"history":"公元前五二五年春，波斯国王冈比西斯二世继父业南征埃及，结好阿拉伯游牧部族穿越西奈沙漠，在尼罗河三角洲东门户佩鲁西姆要塞击败刚即位不久的埃及第二十六王朝末代法老普萨美提克三世。波斯军攻克佩鲁西姆后顺河攻陷孟菲斯，生擒普萨美提克三世，开创波斯统治埃及的第二十七王朝。","sources":"希罗多德·历史·第三卷；波利亚努斯·战略"},
    "gen_chabrias": {"strategic":["公元前四世纪前期，斯巴达倚仗霸主威权横行希腊各邦，甚至悍然派兵袭占底比斯卫城、侵扰雅典外港，激起希腊诸城公愤。雅典顺势组建第二雅典海上同盟，明誓尊重盟邦自治，爱琴海诸岛纷纷归附。","斯巴达见雅典海上声势复苏，立即命海军统帅波利斯率伯罗奔尼撒舰队进驻埃伊纳、基奥斯与安德罗斯一带海面，截击黑海运往比雷埃夫斯的运粮商船，致使雅典城内粮价飞涨、民食告急。为打破海上封锁，雅典紧急装备新造三列桨战舰，推举智勇兼备的名将卡布里亚斯统帅出征；","卡布里亚斯不仅驱散近海敌船护送粮船进港，更主动扬帆直扑基克拉泽斯群岛枢纽纳克索斯，逼迫波利斯赶来海上决战。"],"tactical":["纳克索斯岛海岸与外海水道宽阔，卡布里亚斯正率军在岛上攻城，见波利斯统领优势斯巴达舰队赶来救援，当即收拢将士登舰出海迎敌，自率精锐居右翼，命青年将领福基翁统领左翼。","两军战舰在海面迎头对冲，波利斯亲自坐镇斯巴达右翼猛攻雅典左翼，撞毁多艘雅典战舰并击毙左翼分队长，雅典左翼眼看就要崩溃。","坐镇右翼的卡布里亚斯早已击退当面之敌，见左翼告急并不贪功远追，迅速抽调直属战舰横越海面驰援福基翁，两面夹击将波利斯旗舰所在的斯巴达主力死死咬住。激战之中斯巴达战舰接连被撞沉俘获，波利斯力战不支率残舰败逃；","卡布里亚斯吸取往昔阿吉纽西海战风暴丧师之鉴，止住追兵优先打捞落水同胞与阵亡遗骸。此战系伯罗奔尼撒战败以来雅典首次独立赢得大海战，爱琴海制海权自此重归雅典之手。"],"history":"公元前三七六年九月，第二雅典海上同盟兴起之际，斯巴达海军统帅波利斯率舰队封锁爱琴海并威胁雅典黑海运粮航线。雅典派名将卡布里亚斯率舰队反击，主动围攻纳克索斯岛诱出波利斯舰队决战。海战中雅典左翼一度受挫，卡布里亚斯及时调预备舰增援年轻将领福基翁，反败为胜大破斯巴达海军，重夺爱琴海制海权。注：任务表战场标希马鲁塔，史籍通称纳克索斯海战。","sources":"西西里的狄奥多罗斯·历史丛书·第十五卷；色诺芬·希腊史·第五卷"},
    "gen_chabrias@-357": {"strategic":["公元前四世纪中叶，当年由卡布里亚斯纳克索斯大捷奠基的第二雅典海上同盟逐渐变质，雅典在财政拮据之下频频向爱琴海派驻屯田民并强征军费，令各盟邦深感昔日帝国压迫重演。","在小亚细亚卡里亚总督摩索拉斯的暗中煽动与资助下，公元前三五七年，爱琴海富庶大岛基奥斯联合罗得岛、科斯岛以及海峡重镇拜占庭推翻亲雅典政权，正式结成反雅典同盟，同盟战争骤然爆发。","雅典上下大为震恐，急忙调集陆海重兵首先扑向叛盟核心基奥斯岛，由哈雷斯自陆路进逼城垣，久负盛名的宿将卡布里亚斯则亲自登舰率水师封锁海面，企图一举突入基奥斯海港速战速决。"],"tactical":["基奥斯港湾入口狭窄，港内锚泊着严阵以待的基奥斯及盟邦战舰，岸头亦有守军与城防呼应。交锋打响后，一生未尝败绩的卡布里亚斯豪气不减当年，严令舵手驾乘自己的三列桨座舰一马当先，冒着矢石强行冲开封锁闯入港湾内水。","不料后续雅典各舰畏惧港内交叉拦截，竟迟疑观望未能紧随突入，致使卡布里亚斯孤舰深陷敌群重围。基奥斯战舰从四面八方合拢猛撞，尖锐铜角狠狠刺穿卡布里亚斯座舰船腹，海水汹涌灌入舱底。同船水手与随从见座舰将沉，纷纷跳海游向港外接应的友船逃命；","唯独卡布里亚斯视弃甲弃舰为平生奇耻，坚决拒绝跃水求生，傲立在缓缓下沉的船首甲板上挥矛奋战，直至身中数创壮烈战死，雅典水陆攻势随之受挫败退，同盟各邦终获独立。"],"history":"公元前三五七年，第二雅典海上同盟的重要成员基奥斯、罗得岛、科斯与拜占庭在卡里亚总督摩索拉斯唆使下脱离雅典掀起同盟战争。雅典派哈雷斯统陆军、老将卡布里亚斯率战舰围攻基奥斯城。海战中卡布里亚斯座舰率先突入基奥斯港口，后续舰只未能跟进，座舰遭敌舰群起撞击进水，卡布里亚斯耻于弃舰逃生，持盾力战至死。史料不足：基奥斯守军舰队具体主将姓名失载。","sources":"西西里的狄奥多罗斯·历史丛书·第十六卷；科尔奈利乌斯·奈波斯·卡布里亚斯传"},
    "gen_datis": {"strategic":["公元前四九〇年，波斯帝国彻底扑灭小亚细亚爱奥尼亚叛乱后，大流士一世决意跨海问罪当年曾出舰焚掠撒狄的埃雷特里亚与雅典，一举将帝国威权推向爱琴海西岸。","老练的米底将领达提斯受命挂帅，率领庞大舰队与陆战步骑自奇里乞亚启航，弃走漫长艰险的色雷斯陆路，改由爱琴海中部跳岛西进，一路降服纳克索斯等岛屿，旋即围攻并夷平埃雷特里亚。","初战告捷后，达提斯采纳随军前来的雅典前僭主希庇亚斯献策，率舰队横越海峡，在阿提卡东北岸平坦开阔、便于亲波斯派内应的马拉松海湾抢滩登陆；雅典将军米太亚德闻讯急率公民队伍赶来封堵山口。"],"tactical":["马拉松平原背海面山，南北两端皆有沼泽湿地夹束，达提斯率波斯大军背靠海滩战船列开营垒，以精锐波斯与塞种射手居中、各族仆从部队分居两翼，企图诱雅典人下山或伺机分兵绕海偷袭雅典空城。","两军相持数日，趁波斯骑队暂离前线登船调度之隙，米太亚德突然督率雅典重装方阵排成宽大横列，自山麓跑步猛冲而下，使波斯弓手来不及从容攒射。短兵相接后，达提斯坐镇的波斯与塞种中军凭借骁勇战力一举击穿单薄的雅典中阵，向内陆猛追；","不料波斯左右两翼在雅典加厚方阵的碾压下先行崩溃，逃向海岸与沼泽。雅典双翼并未远追溃敌，而是迅速向内收拢，反过来合围深入的波斯中坚。达提斯见腹背受敌，力战突围抢登战舰，随即绕航欲袭雅典，见米太亚德已先一步赶回布防，遂引舰队东归亚洲。"],"history":"公元前四九〇年夏末，波斯大流士一世命米底将领达提斯与小阿尔塔弗涅斯统水陆远征军横渡爱琴海，降基克拉泽斯诸岛、破埃雷特里亚，在流亡雅典僭主希庇亚斯引导下登陆马拉松湾。对峙数日后雅典将军米太亚德率重装步兵减薄中军、加厚两翼冲锋，达提斯中军虽突破雅典中阵，两翼却溃败被围，波斯军抢船撤退，绕航奇袭雅典未果而还。","sources":"希罗多德·历史·第六卷"},
    "gen_lysander": {"strategic":["公元前五世纪末，绵延二十余载的伯罗奔尼撒战争进入生死决胜关头。雅典历经西西里远征惨败后国库枯竭，完全仰仗经由赫勒斯滂海峡运入的黑海谷物维持全城生计；斯巴达则派遣老谋深算的名将吕山德再度出掌海上兵权，并赢得波斯王子小居鲁士倾囊资助造舰发饷。","吕山德避开雅典主力，乘虚北上奇袭攻占赫勒斯滂海峡东岸富庶的兰普萨库斯，一把掐住了雅典的咽喉粮道。科农与诸位雅典将军闻讯心急如焚，倾全国最后家底组起庞大舰队火速追入海峡，在兰普萨库斯正对面的欧洲海岸羊河滩头抛锚驻泊，急欲逼迫吕山德出海决一死战。"],"tactical":["羊河河口只是一片荒凉开阔的沙石海滩，既无港口掩护，附近又无城邑补给，与吕山德所据粮秣充沛、良港深阔的兰普萨库斯形成鲜明反差。","科农等雅典将领连续四日清早率舰队横渡海峡至港外列阵搦战，吕山德却令斯巴达水手全员披甲登船严阵以待，严禁麾下战舰出港迎击，待傍晚雅典返航后再派快船尾随侦察。雅典诸将日渐骄怠，不听流亡在侧的亚西比德移泊良港之劝，每日收兵回滩后便任由水手四散深入内陆村落买粮歇息。","至第五日午后，尾随侦察船在海峡中央高举铜盾反光发出信号，吕山德一声令下，斯巴达舰队全速划桨横越海峡扑向空虚滩头。雅典滩头营地大乱，绝大部分战舰尚未配齐桨手便被俘获，唯独保持戒备的科农率直属快舰扬帆突围远奔塞浦路斯；雅典海上命脉就此断绝，次年饥困投降。"],"history":"公元前四〇五年秋，斯巴达海军统帅吕山德在波斯王子小居鲁士财力支持下重建舰队，进占赫勒斯滂海峡重镇兰普萨库斯以断雅典黑海粮道。雅典将领科农等率舰队泊于海峡对岸无港口的羊河即埃哥斯波塔米海滩，连日邀战而吕山德坚壁不出；第五日趁雅典水手离船登岸觅食，吕山德率全舰队闪电横渡突袭，几乎全歼雅典海军，科农仅率少数战舰逃往塞浦路斯。","sources":"色诺芬·希腊史·第二卷；普鲁塔克·吕山德传"},
    "gen_lysander@-395": {"strategic":["公元前四世纪初，斯巴达虽在吕山德筹划下打赢伯罗奔尼撒战争成为全希腊霸主，但其独断专行的霸道行径很快激起昔日盟友底比斯与科林斯的强烈不满；正在小亚细亚遭斯巴达王阿格西劳斯进攻的波斯帝国亦暗遣使者携重金游说希腊各邦起兵反斯巴达。","公元前三九五年，底比斯借故介入福基斯边衅，并成功与世仇雅典结成反斯巴达同盟。早就渴望惩治底比斯的吕山德力劝斯巴达发兵，定下南北两路夹击彼奥提亚的方略；","国王保萨尼亚斯统领伯罗奔尼撒主力北上，吕山德先行赶赴福基斯纠集北方盟军并成功策反重镇奥尔霍迈诺斯，约定某日会师于科帕伊斯湖南岸要冲哈利亚托斯。"],"tactical":["哈利亚托斯坐落于科帕伊斯湖南岸山麓与湖泽之间的狭窄通道，地势险要。吕山德率北路福基斯与奥尔霍迈诺斯盟军准时进抵城外，却不见南路保萨尼亚斯踪影，原来他派去联络会师的信使已在半途被底比斯巡骑截获，底比斯主力正星夜兼程赶来驰援。","性情刚烈急躁的吕山德不愿在城外空耗待援，误判城内孤立无助，遂亲自率军迫近哈利亚托斯城墙下方试图劝降并寻机强攻。不料底比斯先头部队早已潜入城中，而底比斯城外增援大军恰在此时自山脊后方杀到；","城门骤然大开，城内外底比斯重步卒与骑队两面夹攻，将紧贴墙根、来不及展开方阵的吕山德前锋打得措手不及。吕山德在墙下混战中当场阵亡，部众败退上山虽借险坡反挫追兵，但次日赶到的斯巴达国王见主将已陨、雅典大军又至，只得乞和收尸黯然撤军，科林斯战争全面爆发。"],"history":"公元前三九五年，因斯巴达霸权专横及波斯黄金暗中策动，底比斯联合雅典挑起科林斯战争。斯巴达制定南北分进合击方略，命吕山德自福基斯率北路联军、国王保萨尼亚斯自伯罗奔尼撒率南路主力会师哈利亚托斯。吕山德提前抵达并策反奥尔霍迈诺斯后，不等保萨尼亚斯赶到便逼近哈利亚托斯城墙，遭城内守军与赶来的底比斯主力前后夹击，吕山德阵亡，斯巴达霸业由此受挫。史料不足：底比斯方面具体统兵主将姓名史书未详载。","sources":"色诺芬·希腊史·第三卷；普鲁塔克·吕山德传"},
    "gen_lysander@-406": {"strategic":["公元前四〇七年至前四〇六年之交，伯罗奔尼撒战争的海上天平原本正朝雅典倾斜，重返雅典统帅之位的奇才亚西比德连战皆捷，收复海峡多处失地。危急时刻，斯巴达任命深沉善谋的吕山德出任海军统帅进驻小亚细亚重镇以弗所；","吕山德巧妙结交新任小亚细亚总督的波斯王子小居鲁士，争取到大笔波斯黄金提高水手军饷，引得大批熟练桨手从雅典舰队叛逃投奔斯巴达。亚西比德率雅典舰队进驻以弗所西北不远的诺提姆海角严密监视，吕山德却自知新军尚待磨合，闭港坚拒不出。","未几亚西比德因军饷短缺抽身北赴福凯亚，临行再三严令留守诺提姆的亲信舵手安提奥库斯绝不可主动挑战吕山德，一场改变两邦帅印归属的海战却悄然酝酿。"],"tactical":["诺提姆海角与以弗所海港隔湾相望，海面开阔，往来动静彼此清晰可见。急于立功炫耀的安提奥库斯将主帅禁令抛诸脑后，竟效仿往昔昔济库斯诱敌故智，亲驾座舰率少量快船径直划到以弗所港嘴，贴着斯巴达船头叫骂挑衅，妄图引诱吕山德追出再以潜伏舰船夹击。","吕山德洞察其轻率孤进，先遣精锐快舰迅猛扑出，一举撞沉冲在最前的安提奥库斯座舰并将其击毙；随后见诺提姆港内其余雅典战舰惊闻变故，未经统一编队便零零散散陆续赶来救应，吕山德当机立断下令斯巴达全舰队排成严整战列倾巢出击。","散乱无章的雅典船队迎头撞上严阵以待的斯巴达主力，接连被撞毁俘获，狼狈逃回萨摩斯岛；此战虽非灭顶之灾，却令雅典民众迁怒罢免了唯一的帅才亚西比德，为吕山德日后终结战争铺平了道路。"],"history":"公元前四〇六年春，新任斯巴达海军统帅吕山德驻节以弗所，得波斯小居鲁士增饷厚募水手，与驻泊诺提姆海角的雅典名将亚西比德隔海对峙。趁亚西比德分兵北上并严令副将舵手安提奥库斯不得出战之际，安提奥库斯违命率小队战舰赴以弗所港前诱敌，吕山德精准反击击沉安提奥库斯座舰并击败仓促赶来的雅典主力，直接导致亚西比德遭雅典罢黜流放。","sources":"色诺芬·希腊史·第一卷；普鲁塔克·吕山德传；普鲁塔克·亚西比德传"},
    "gen_miltiades": {"strategic":["公元前四九〇年夏末，波斯远征统帅达提斯攻灭优卑亚重镇埃雷特里亚，将其民众尽数掳为奴隶，随即率领遮天蔽日的波斯舰队横渡海峡，在距离雅典不远的马拉松海湾登陆，新兴的雅典城邦面临灭顶之灾。雅典一面派快跑信使星夜赶赴斯巴达求援，一面紧急动员公民重装方阵；","然而斯巴达人囿于宗教月圆之忌迟迟未能发兵，仅有小邦普拉提亚倾城赶来助阵。雅典诸将聚议于山前，半数畏惧波斯声势主张退守城垣；","早年曾在色雷斯熟稔波斯战法的米太亚德深知一旦退缩，城内亲波斯派必生内变，遂慷慨陈词说服执政官投下关键一票，督率希腊公民方阵进驻马拉松西侧山麓，死死卡住通往雅典的山道。"],"tactical":["马拉松平原东临海湾、西倚群山，米太亚德占据林木掩映的山坡高地扎营，令波斯骑队无从冲击，与海滩上的达提斯大军相持数日。及至轮到米太亚德执掌全军号令之日，侦知波斯军分调骑队异动，他当机立断布下奇阵；","为防被面宽势众的波斯大军包抄侧翼，故意将雅典中军纵深削薄，把主力厚集于左右两翼，与敌阵等宽展开。号角吹响，全副青铜重甲的希腊公民迈开大步疾奔冲过开阔地，顶着波斯箭雨狠狠撞上敌阵。","雅典单薄的中军在波斯精锐反扑下节节后退，但厚重的左右双翼却以长矛铜盾轻易撕碎波斯侧翼仆从阵线；米太亚德严令双翼止步回旋，由外向内合击追击过深的波斯中坚。波斯军阵脚大乱，争相奔向海滩抢船；","米太亚德更率疲师急行赶回雅典城外列阵，迫使绕海赶来的达提斯望城兴叹而返，一战打破了波斯不可战胜的神话。"],"history":"公元前四九〇年九月，波斯将领达提斯率远征军登陆阿提卡马拉松平原，雅典城内战和莫衷一是，曾在色雷斯熟知波斯战法的将军米太亚德说服军事执政官卡利马科斯投票主战，与普拉提亚盟军据山扼守。轮值主帅之日米太亚德果断减薄中军、厚集两翼跑步冲阵，两翼包抄击溃波斯军，随后强行军回防雅典逼退波斯舰队。","sources":"希罗多德·历史·第六卷；科尔奈利乌斯·奈波斯·米太亚德传"},
    "gen_themistocles": {"strategic":["公元前四八〇年，波斯国王薛西斯亲统空前浩大的水陆大军架桥越过赫勒斯滂海峡，沿爱琴海北岸向希腊本土滚滚压来，北希腊诸邦望风归降。","早在战云初起之时，富有远见的雅典领袖地米斯托克利便说服公民大会将劳里昂银矿收益全部用于建造新式三列桨战舰，使雅典一跃成为希腊海上支柱，并主动把联军海军名义统帅权让予斯巴达以换取各邦团结。为阻遏波斯水陆协同并进之势，希腊同盟定下水陆联防方略；","陆军扼守温泉关天险，地米斯托克利则率希腊联合舰队北上进驻优卑亚岛水道，迎堵阿凯门尼斯等人统领的波斯王家舰队，绝不容波斯船队绕向温泉关后背。"],"tactical":["优卑亚岛外围海峡水路曲折，北起阿尔特米西昂海角，南连卡里斯托斯外海，风急礁多。阿凯门尼斯所在的波斯舰队刚抵马格尼西亚海岸便遭猛烈风暴重创，但存留舰群规模依旧远超希腊联军，波斯统帅部还另遣分舰队绕航优卑亚东岸企图自南口卡里斯托斯方向包抄希腊后路。","地米斯托克利稳住一度想要南撤的盟邦诸将，趁午后天色将晚发动突袭；希腊战舰先聚作环形防御阵，待波斯舰群围拢之际骤然听号向四面辐射猛撞，一举击沉俘获敌舰甚众，当夜暴风雨更将绕航外海的波斯分舰队拍碎于礁岸。","其后波斯主力排成半月阵全力压上，两军在狭窄海面浴血对撞，难分高下。入夜传来温泉关失陷噩耗，水陆防线失去依托，地米斯托克利遂率舰队井然有序南撤萨拉米斯，为后续海上决战保存了制胜火种。"],"history":"公元前四八〇年夏末，波斯王薛西斯水陆大举侵希，雅典政治家兼将领地米斯托克利力主打造三列桨战舰，配合温泉关陆军扼守优卑亚岛北端阿尔特米西昂海峡，与波斯阿凯门尼斯等统率的庞大舰队连战三日。波斯分舰队绕航优卑亚南端卡里斯托斯一带遭风暴覆没，双方海战互有损伤；因温泉关失守，地米斯托克利组织舰队有序南撤萨拉米斯。注：任务表战场标卡里斯托斯，主交战海面实为阿尔特米西昂。","sources":"希罗多德·历史·第八卷；普鲁塔克·地米斯托克利传"},
    "gen_themistocles@-480": {"strategic":["公元前四八〇年秋，波斯王薛西斯一世突破温泉关防线后长驱直入中希腊，雅典全城民众在将军地米斯托克利果断疏散下渡海撤往萨拉米斯岛，空城随即被波斯大军付之一炬。","眼见雅典化为焦土，停泊在萨拉米斯海湾的伯罗奔尼撒各邦舰长惊惶失措，纷纷要求放弃萨拉米斯、南撤科林斯地峡保卫各自家园。","地米斯托克利深知一旦离开狭窄水道退往开阔外海，希腊联合舰队必被数量悬殊的波斯大舰队分割吞没，遂以率雅典全体舰船远迁意大利相要挟，逼迫联军统帅留驻萨拉米斯；","为防盟友乘夜溜走，他又暗遣忠仆驾小舟潜赴波斯大营，向薛西斯一世诈称希腊人内讧将逃，诱使急于毕其功于一役的波斯舰队主动钻入萨拉米斯海峡。"],"tactical":["萨拉米斯海峡夹在岛屿与阿提卡海岸之间，水道曲折逼仄，薛西斯一世亲在岸边埃加莱奥斯山头设下宝座观战，命波斯舰队连夜划桨封锁海峡出口，水手整夜劳顿未得合眼。","天明之后，地米斯托克利故意令希腊三列桨战舰缓缓后退，将求胜心切的波斯腓尼基与爱奥尼亚分舰队深深引入最狭窄的海湾咽喉。","待上午海峡涌风准时掀起巨浪，舰体高大笨重的波斯战船随波摇晃、船桨相互纠缠挤作一团，地米斯托克利看准良机吹响反击号角，舰身低矮灵巧的希腊战舰乘风猛冲而出，以青铜舰首狠狠撞碎敌船侧舷。波斯前排战舰欲退，后排战舰却为在薛西斯一世面前争功仍拼命前挤，海峡顿成修罗屠场；","波斯海军遭受毁灭性重创，薛西斯一世唯恐归路浮桥被断，只得率主力仓皇退回亚洲，希腊文明由此转危为安。"],"history":"公元前四八〇年九月，温泉关失陷、雅典被焚后，希腊联合舰队退集萨拉米斯岛与阿提卡之间的狭窄海峡。伯罗奔尼撒诸将欲南撤科林斯地峡，雅典统帅地米斯托克利力争留战，更密遣家仆向波斯王薛西斯一世诈报希腊舰队将逃，诱使波斯舰队连夜驶入狭窄水道，天明借海风与地形重创波斯海军，成为希波战争决定性转折点。","sources":"希罗多德·历史·第八卷；埃斯库罗斯·波斯人；普鲁塔克·地米斯托克利传"},
    "guyashu_shamushi": {"strategic":["公元前十八世纪初，两河流域城邦林立，阿摩利诸王竞逐商道与沃土。沙姆希阿达自上美索不达米亚崛起，先后夺取阿舒尔与埃卡拉图姆，将底格里斯河上游连成强盛疆域，唯独西南方向仍受马里王国掣肘。马里坐落于幼发拉底河中游要冲，控扼叙利亚通往巴比伦的水陆商路；","马里王亚赫敦林曾西抵地中海立碑扬威，与亚述屡生边衅。未几马里宫廷突发变乱，王室威权摇摇欲坠，周边游牧部族亦蠢蠢欲动。沙姆希阿达见良机已至，决意打通幼发拉底河商路，亲统亚述大军顺河南下，兵锋直逼马里城垣。"],"tactical":["马里城背倚幼发拉底河干流，凭人工运河与厚重土砖城垣构成河谷防线；亚赫敦林一方据守城池，并指望河谷游牧部族自外策应。沙姆希阿达进抵马里外围后，先分兵弹压沿河诸镇，切断城外游牧援军的往来通道，使马里化作河畔孤城。","亚述大军随即合围城池，沿运河堤岸步步推进，连日猛攻城防薄弱之处。城内本就人心惶惶，外援断绝之下防线终告瓦解，亚述军破城而入。此役之后亚赫敦林败亡，沙姆希阿达命王子留镇马里，幼发拉底河中游尽入亚述版图，上美索不达米亚自此联为一统。"],"history":"约公元前一七九六年，上美索不达米亚霸主沙姆希阿达乘幼发拉底河中游重镇马里内乱之机，进军占领马里，置幼子亚斯马赫阿达德镇守，构建起横跨上两河的古亚述疆域。异说与史料不足：马里王室泥板载马里王亚赫敦林先死于宫廷侍从刺杀，其子苏穆亚曼短暂继位后亚述军方夺取马里，任务表将沙姆希阿达与亚赫敦林径列为攻守敌手；围攻马里城的具体交战细节泥板阙载。","sources":"马里王室泥板文书；亚述王表"},
    "guyashu_tigelate": {"strategic":["公元前八世纪中叶，新亚述帝国在提格拉特锐意改革下建立起常备职业军制，国势重回巅峰，大举向地中海东岸扩张。","叙利亚重镇亚兰大马士革首当其冲，国王利汛不甘长年向亚述纳贡称臣，遂联合以色列王国结成反亚述同盟，并出兵围攻拒绝入盟的犹大王国，企图整合黎凡特诸邦共同抗拒亚述西进。犹大王走投无路，遣使携圣殿金银向亚述称臣求救。","提格拉特正欲铲除西方隐患，当即挥师南下，先沿地中海海岸扫荡非利士，截断埃及北援之路，继而席卷以色列北境，将反亚述同盟的羽翼逐一剪除。孤立无援的利汛被迫退回都城，提格拉特统率亚述主力回师合围大马士革。"],"tactical":["大马士革坐落于反黎巴嫩山东麓绿洲，倚赖巴拉达河水灌溉，城垣坚厚，城外果木成林、村镇密布。利汛在城外前哨交锋失利后，率残部退入大马士革闭门死守，指望凭高墙与城内储粮拖垮远征之师。","提格拉特并不急于驱兵蚁附硬攻，而是分遣部队彻底扫平大马士革周遭属邑，砍伐城外成片果园以断绝其生计，同时筑起严密围墙与攻城土山，将大马士革围得水泄不通。在漫长的围困与攻城槌反复撞击之下，城内粮尽援绝，防线终告崩溃，亚述大军破城而入。","利汛被擒获处死，城中工匠与民众大批被迁往亚述腹地，提格拉特废除亚兰王位，将其全境划为亚述直辖行省，叙利亚诸邦自此尽数俯首。"],"history":"公元前七三二年，新亚述国王提格拉特应犹大王亚哈斯求援，继扫荡腓尼基与以色列北境后，主力合围反亚述同盟首脑亚兰大马士革国王利汛的都城大马士革。经严密围困与摧毁城外园林属邑，亚述攻破大马士革，处死利汛，将亚兰故地改置为亚述行省，迁徙其民，终结了亚兰大马士革王国。","sources":"提格拉特帕拉沙尔三世铭文；列王纪下·第十六章"},
    "hesitiya_yiasong": {"strategic":["公元前四世纪七十年代，正当斯巴达、底比斯与雅典在中南希腊缠斗不休之际，北方肥沃广袤的色萨利平原悄然崛起一位雄主。费莱僭主伊阿宋凭借过人谋略与严酷训练，打造出精悍常备雇佣军与菱形骑队；","他软硬兼施收服法萨卢斯等色萨利各大贵族城邦，获推举为统揽色萨利全境兵马的最高统帅，连伊庇鲁斯与马其顿皆与之结盟。统一北境之后，伊阿宋志在问鼎全希腊霸权乃至东征波斯，目光随即投向温泉关以南的中希腊门户福基斯与泛希腊圣地德尔斐。","公元前三七四年，伊阿宋统率色萨利劲旅南下压境，中希腊诸邦与雅典方面深感震动，福基翁一方依托德尔斐山地险隘严密戒备，南北势力在圣地外围形成剑拔弩张之势。"],"tactical":["福基斯境内帕尔纳索斯山峦耸峙，通往德尔斐圣地的山谷通道狭窄崎岖，全然不利于色萨利引以为傲的重骑队展开冲锋。福基翁一方深知平原野战难敌伊阿宋久经战阵的雇佣劲旅，遂抢先占据德尔斐外围险要山口与高地壁垒，以步卒据险设防，扼住南进咽喉。","伊阿宋昼夜兼程疾行抵近，审察山势险恶，明白强行仰攻必损精锐，遂充分发挥麾下轻盾步卒与骑队机动迅捷之长，分兵袭扰福基斯外围邑落与交通要道，以雷霆军威展开武力慑压。防守一方被困于险隘之内不敢轻出决战，最终被迫在通道与边地事务上作出妥协；","伊阿宋既已打通南下中希腊的走廊并立威圣地周边，便从容全师北还，色萨利自此成为左右希腊大局的北方强权。"],"history":"公元前三七四年前后，色萨利费莱僭主伊阿宋统一色萨利全境并获推举为全境最高统帅塔戈斯，拥精锐色萨利骑兵与雇佣军南向经略中希腊，介入福基斯与德尔斐周边事务，声威震动希腊诸邦。史料不足与异说：色诺芬希腊史与狄奥多罗斯载伊阿宋南下经略福基斯、拆毁赫拉克利亚城防并觊觎德尔斐皮提亚祭典主导权，但古典史料未载雅典将领福基翁于此役在德尔斐统兵与伊阿宋正面交战，播报依任务表设定概括双方扼险对峙而不妄增细节。","sources":"色诺芬·希腊史·第六卷；西西里的狄奥多罗斯·历史丛书·第十五卷"},
    "heti_muwatali": {"strategic":["公元前十三世纪，赫梯帝国雄踞小亚细亚，将叙利亚北部诸邦纳入羽翼，视奥龙特斯河流域为帝国南疆屏障。然而埃及新法老拉美西斯即位后频频北向用兵，先定迦南沿海，又诱使赫梯的重要藩属阿穆鲁背盟投埃，直接威胁赫梯在叙利亚的根基。","赫梯王穆瓦塔利深知一旦卡迭石有失，北叙利亚诸邦必将纷纷动摇，遂将王廷南移以便调度南方军务，同时征集帝国本部与小亚细亚诸盟邦兵马倾力南下。","面对锐意北进的埃及各路军团，穆瓦塔利并未仓促迎头硬拼，而是率领大军提前进抵卡迭石城外，决意在奥龙特斯河畔给骄兵深入的埃及法老布下一道死局。"],"tactical":["奥龙特斯河水绕过卡迭石城垣，城东地势开阔，便于战车集结藏匿。穆瓦塔利将大军主力隐蔽于卡迭石城背视线之外，故意派出牧人细作向埃及前锋诈称赫梯军远在北方阿勒颇，诱使拉美西斯孤军先行渡河安营。","待侦知埃及前锋与后续军团前后脱节，穆瓦塔利当即下令重型战车涉过浅滩，自侧翼猛扑尚在行途中的埃及次队，将其一举冲散，紧接着乘势杀入埃及王营。赫梯车队势如破竹，眼看就要生擒拉美西斯，不料前锋车兵见营中财货丰厚便下车争抢，攻势顿时迟滞；","恰逢埃及侧翼援军赶到反扑，穆瓦塔利虽增派预备车队再战，终因河岸狭窄受阻而退回东岸。次日埃军不敢再攻而引兵南撤，穆瓦塔利乘胜收复阿穆鲁，稳固了赫梯在叙利亚的霸权。"],"history":"公元前一二七四年五月，赫梯帝国国王穆瓦塔利倾全国及诸属国之力南下叙利亚，在奥龙特斯河畔卡迭石设伏迎击埃及法老拉美西斯。穆瓦塔利遣人诈降诱使埃及前锋孤军深入，随即发战车渡河截断埃军队列、围攻法老营垒；因车兵贪掠营中辎重且埃及援军及时赶到，未能全歼埃军，但成功迫使埃及撤军，保住卡迭石并夺回阿穆鲁。","sources":"哈图沙泥板文书；卡迭石铭文"},
    "jialedi_nibujianisa": {"strategic":["公元前六世纪初，新巴比伦帝国取代亚述成为西亚霸主，与尼罗河畔的埃及第二十六王朝反复争夺黎凡特走廊。巴比伦王尼布甲尼撒早年曾出兵降服犹大王国，废黜旧王，亲手扶植王叔西底家登基，令其宣誓效忠巴比伦。","然而西底家在位九载后，受朝中亲埃派贵族怂恿，见埃及新法老积极北上干预叙利亚事务，便公然撕毁盟誓，拒向巴比伦纳贡，并与埃及及周边小邦暗通款曲。","尼布甲尼撒决不容许通往埃及的战略门户失控，当即统率巴比伦大军西出两河，先扫荡犹大山地外围要塞拉吉与亚西加，剪除耶路撒冷的屏障羽翼，继而将主力合围至犹大都城耶路撒冷城下。"],"tactical":["耶路撒冷雄踞犹大山地脊梁，东西南三面皆为深邃险峻的汲沦谷与欣嫩子谷，唯北面地势稍缓；西底家依托坚厚石墙储粮固守，日夜期盼埃及援军北上解围。尼布甲尼撒命大军环城构筑高耸围垒与守望台，严密封锁四出入城通道；","期间埃及果然发兵北援，尼布甲尼撒果断抽调主力迎头击退埃军，旋即回师收紧包围圈，彻底粉碎守军外援之望。围困旷日持久，城中粮草断绝，饥荒与瘟疫蔓延，守卒无力再支。公元前五八七年盛夏，巴比伦攻城器械撞破北面城垣缺口，大军汹涌入城；","西底家趁夜率亲随自王家花园暗门突逃约旦河荒原，被巴比伦追骑擒获。尼布甲尼撒下令拆毁城墙，焚毁圣殿与王宫，将犹大贵族工匠迁往两河，犹大王国就此覆亡。"],"history":"公元前五八九年至前五八七年，因犹大王西底家背叛新巴比伦、转结埃及法老合弗拉，新巴比伦国王尼布甲尼撒亲统大军围攻耶路撒冷。期间巴比伦军一度击退来援的埃及军队，合围十余月后城中绝粮，公元前五八七年夏攻破北墙，擒获外逃的西底家，焚毁第一圣殿与王宫，掳其民入巴比伦，犹大亡国。注：任务表敌方势力标为以色列，实为犹大王国；破城年份另有前五八六年说。","sources":"列王纪下·第二十五章；耶利米书；巴比伦编年史"},
    "jialedi_nibujianisa@-605": {"strategic":["公元前七世纪末，亚述帝国都城尼尼微虽已倾覆，近东霸权的归属却仍未尘埃落定。","埃及法老尼科二世唯恐新兴的新巴比伦独霸西亚，借口援助亚述残存势力大举北上，在米吉多击杀犹大王约西亚，一路将防线推进至幼发拉底河上游西岸要塞卡基米什，与巴比伦军隔河拉锯数载并屡挫巴比伦前哨。","公元前六〇五年，年老多病的巴比伦国王那波帕拉萨留在都城坐镇，将全国最精锐的野战大军悉数交付文武兼资的王储尼布甲尼撒统领。尼布甲尼撒肩负开疆重任溯河北上，直抵卡基米什对岸，一场决定叙利亚与迦南归属谁手的生死决战就此降临。"],"tactical":["卡基米什紧扼幼发拉底河上游西岸渡口，高城巨垒俯瞰河面，埃及法老尼科二世集结埃及精兵与希腊雇佣步卒重兵扼守浅滩，以为巴比伦军绝难正面强渡天险。","尼布甲尼撒审察形势，并未在城下正面硬拼渡口，而是秘密率主力在下游另觅渡处悄然济河，迅速迂回至卡基米什西侧陆地，从侧背将埃军后路截断。尼科二世大惊失色，急率主力出城迎战；两军先在城外原野展开惨烈白刃厮杀，继而杀入城垣街巷之中。","尼布甲尼撒身先士卒督军猛攻，城内建筑燃起大火，埃及阵线在巴比伦步骑排山倒海的冲击下全面崩盘。尼科二世仅率残兵仓皇南逃，尼布甲尼撒乘胜紧追至哈马特再歼埃军余部，整个叙利亚与巴勒斯坦自此尽归新巴比伦号令，埃及再无力北争西亚。"],"history":"公元前六〇五年夏，埃及第二十六王朝法老尼科二世借扶助亚述残余之名占据幼发拉底河上游重镇卡基米什，企图阻止新巴比伦西进叙利亚。年迈的巴比伦王那波帕拉萨命王储尼布甲尼撒全权统军北上，尼布甲尼撒绕渡幼发拉底河突袭卡基米什，内外夹击彻底歼灭埃及主力，尼科二世败逃，新巴比伦自此尽收黎凡特霸权。","sources":"巴比伦编年史；耶利米书·第四十六章；弗拉维奥·约瑟夫斯·犹太古史"},
    "jin_xianzhen": {"strategic":["公元前七世纪前期，周王室威权旁落，齐桓公身后中原霸主虚位，南方楚国乘势大举北进，先后慑服陈、蔡、郑、许诸国，楚令尹子玉更统兵合围亲晋的宋国都城商丘。宋国急遣使赴晋求救，新即位不久的晋文公意欲借救宋立威诸侯，却顾忌楚联军势大。","中军元帅先轸献策，主张不必径赴商丘硬拼，转而攻打新附于楚的曹、卫两国，迫使楚军回救以解宋围。晋文公依计而行，一举破曹服卫，更私许复曹卫之田使之绝楚，又激怒齐秦共同参战。","楚成王本欲见好就收，刚愎骄横的子玉却执意请战，挥师北上追击晋军，先轸遂统晋师迎向卫地，晋楚争霸中原的决战一触即发。"],"tactical":["卫地城濮原野与丘陵相间，外围有莘墟高地与泽薮阻隔。子玉率楚军咄咄逼近，晋军依当年流亡受礼之诺主动后撤三舍，驻营城濮，既在诸侯面前占尽大义，又将孤军深入的楚师引至预设战场。两军列阵交锋，晋下军佐胥臣命给战马蒙上虎皮，悍然直冲子玉右翼的陈蔡联军；","陈蔡士卒本无死战之心，马群受惊顿时奔溃，楚右翼先行瓦解。随后晋上军竖起双旆假装败退，诱使楚左翼急起直追，阵形拉长暴露侧翼；先轸看准战机，亲率晋中军精锐拦腰横击，上军亦回身反扑，两面夹击将楚左军彻底击溃。子玉见左右双翼尽折，紧急收拢中军残部退走，归途引咎自尽；","晋国由此在践土会盟受周天子策命，开启中原霸业。"],"history":"公元前六三二年四月，晋文公重耳以先轸为中军元帅南下救宋，伐曹攻卫以致楚师，与楚令尹子玉会战于卫地城濮。晋军先退避三舍以报楚惠、骄敌致师，决战时下军佐胥臣蒙虎皮冲溃陈蔡右军，上军狐毛设二旆佯退诱楚左军追击，先轸率中军横击夹攻大破楚师，子玉败归自杀，晋文公践土会盟确立中原霸主地位。","sources":"左传·僖公二十八年；史记·晋世家"},
    "jin_xianzhen@-627": {"strategic":["公元前六二七年，称霸中原的晋文公与郑穆公相继辞世，西方秦穆公不听老臣蹇叔痛哭苦谏，私下轻信留戍郑都的内应密报，派遣大将孟明视统兵越过晋国南境远道偷袭郑国。","秦师行至滑国，恰遇机警的郑国商人弦高以牛犒师并派人飞报郑廷，孟明视见郑已有备，不敢再进，顺手袭灭晋之同姓小邦滑国后掉头西归。晋廷闻报朝野震动，有人顾忌秦穆公昔日拥立晋文公之旧恩不愿构怨；","中军元帅先轸勃然进言，指出秦趁晋丧君越境袭滑乃存心轻侮，一日纵敌必遗数世之患。新立的晋襄公毅然采纳先轸之策，将白色丧服染黑披甲出征，先轸遂调集晋军并联合熟悉山地的姜戎部众，星夜赶赴秦军归国必经的殽山绝谷张网以待。"],"tactical":["殽山横亘于黄河以南、洛阳以西，分南北两座险峰，谷深林密、栈道狭长，车马穿行其间进退维谷，正是老臣蹇叔临别预言晋人必在此设伏的绝地。孟明视率领远道疲敝、满载滑国战利品的秦军步入殽山峡谷，因轻视晋国新丧，沿途既未派斥候搜山，车队又在狭窄山道上拉成冗长一线。","待秦军全数钻入袋形谷底，先轸一声号令，预先埋伏在两侧绝壁高处的晋军与姜戎将士滚木礌石齐下，先行封死东西两端谷口断绝退路，随即居高临下四面掩杀。秦军兵车在狭谷中无法回旋列阵，将士插翅难逃，全军覆没于山谷之中，主帅孟明视与副将西乞术、白乙丙悉数被晋军生擒；","此战一举折断秦穆公东进争霸之翼，使秦国此后数代只能向西开拓西戎。"],"history":"公元前六二七年春，秦穆公违背蹇叔苦谏，遣孟明视、西乞术、白乙丙率军越晋境远袭郑国；因郑商弦高犒师示警，秦军灭滑而还。时晋文公新丧，中军元帅先轸力排众议，劝说晋襄公墨绖从戎，联姜戎埋伏于殽山险峻峡谷之中，截断首尾全歼秦军，生擒孟明视等三帅，彻底锁死秦国东进中原之路。","sources":"左传·僖公三十三年；史记·晋世家；史记·秦本纪"},
    "mi_chu_xionglv": {"strategic":["公元前六世纪初，晋楚两国围绕中原枢纽郑国展开激烈拉锯，郑国夹在南北两大强权之间朝晋暮楚，岁无宁日。楚庄王熊旅亲政后励精图治、平定若敖氏之乱，国势蒸蒸日上，遂亲统楚师北围郑都新郑，经数月围攻迫使郑襄公肉袒牵羊出降。","晋国闻讯遣中军元帅荀林父统兵南下救郑，然而晋师行至黄河岸边时，郑国早已与楚结盟罢兵。荀林父见救郑已迟，本欲隔河驻守待楚师退去便引兵北返，中军佐先縠却恃勇骄横，斥退兵为怯懦，竟擅率所部先行渡过黄河。晋军号令既裂，荀林父唯恐先縠孤军覆没，只得令全军南渡；","熊旅采纳伍参进言，北进与心怀狐疑的晋军在郑郊邲地迎面相逢。"],"tactical":["郑郊邲地北靠黄河天险，晋军背水扎营，军中主帅荀林父与诸卿战和不一，戒备松懈，仍在与楚军往来议和。恰逢晋将魏锜与赵旃求官未遂，故意擅赴楚营挑衅邀战，晋营又派出车骑接应，扬起漫天尘土。","楚庄王熊旅登车望见晋营尘嚣纷乱，断定晋军号令不一，当即令孙叔敖挥军全线突击，楚右军直捣晋上军，左军包抄晋下军，精锐工尹齐部猛冲晋中军。晋军猝不及防，尚未列阵便遭楚车骑席卷；荀林父惊慌失措，下令全军抢渡黄河逃命，并悬赏先渡者有赏。","中下两军顿时大乱，溃兵争攀渡船，船上士卒甚至挥刀砍断攀船者的手指，唯上军设伏殿后方得幸免。此役晋国霸业重挫，熊旅饮马黄河，正式确立楚国中原霸主之位。"],"history":"公元前五九七年夏，楚庄王熊旅围攻郑国迫其降楚，晋国中军元帅荀林父率师救郑，进抵黄河闻郑已降楚欲还，中军佐先縠违命独渡黄河，晋军被迫全军济河屯于邲地。两军和谈之际因魏锜、赵旃挑衅破局，熊旅乘晋军将帅失和、未及成列发动突袭，晋军大溃争舟渡河，楚国一战夺得中原霸权。","sources":"左传·宣公十二年；史记·楚世家"},
    "sumeier_nabopalasa": {"strategic":["公元前七世纪后期，曾横行西亚的亚述帝国在亚述巴尼拔身后陷入王位内战，国力急剧衰耗，被压迫已久的属邦纷纷思变。巴比伦首领那波帕拉萨乘乱在南方起兵逐走亚述驻军，于巴比伦自立为王，开创迦勒底新巴比伦基业，并与亚述拉锯苦战十余载。","与此同时，东方伊朗高原上的米底王国亦整顿兵马西进，在攻陷亚述宗教故都阿舒尔城外与巴比伦正式缔结盟约。面对南北两强联手进逼，亚述王伊什昆节节败退，被迫收缩残存兵力退保帝国都城尼尼微；","公元前六一二年盛夏，那波帕拉萨统率巴比伦大军溯底格里斯河北上，与米底盟军会师于尼尼微城下。"],"tactical":["尼尼微矗立于底格里斯河东岸，外有高耸宽厚的双层城垣，城内更有科斯尔河穿流而过，防御工事冠绝西亚，伊什昆督率亚述残存禁卫凭坚城作困兽之斗。","那波帕拉萨与米底联军将都城严密合围，在长达数月的攻防中连续发动猛烈总攻，亚述守军虽拼死击退前番登城之敌，但外援断绝、兵力日减。","适逢雨季河水暴涨，湍急洪流冲刷软化了临水地段的泥砖城基，联军工兵趁势掘毁河防与墙垣缺口，巴比伦与米底士卒顺着干涸河床与坍塌缺口一举杀入内城。巷战惨烈展开，伊什昆退守王宫，在熊熊烈火中与宫室同归于尽，尼尼微全城遭彻底焚掠夷平；","称霸西亚的亚述帝国自此崩塌，两河流域霸权转归新巴比伦。"],"history":"公元前六一二年夏，新巴比伦王国开国君主那波帕拉萨与米底国王基亚克萨雷斯会师底格里斯河东岸，合围亚述帝国都城尼尼微。联军围城三月，借河水暴涨冲毁城垣缺口攻入内城，亚述末代君主辛沙尔伊什库恩即伊什昆死于宫火之中，尼尼微化为废墟，统治西亚数世纪的亚述帝国走向覆亡。注：任务表我方势力写作乌鲁克，实为新巴比伦王国。","sources":"巴比伦尼尼微陷落编年史；希罗多德·历史"},
    "wei_wuqi": {"strategic":["公元前四世纪初，韩赵魏三家分晋不久，魏国在魏文侯任用李悝变法与名将吴起治军之下率先强盛，成为战国初期首屈一指的霸主。","吴起受命出任西河郡守，连年挥师西进，将秦国在黄河以西、洛水以东的大片河西沃土尽数夺入魏国版图，直接把防线推进至华山脚下，死死扼住秦人东出函谷的咽喉。秦国上下视丧失河西为奇耻大辱，无日不思夺回故土。","及至魏文侯去世、魏武侯新立，秦惠公以为魏国新君初政有机可乘，于公元前三八九年倾发全国兵马大举东进，猛扑魏国河西门户阴晋；西河危急，吴起主动向魏武侯请缨，一场关乎河西归属与秦魏国运的大战就此拉开。"],"tactical":["阴晋南依秦岭华山余脉，北控渭洛交汇原野，乃秦军东出与魏军守险的必争之地，秦惠公亲督浩荡秦师压境筑垒，声势逼人。西河魏卒素受吴起恩信感召，闻秦军来犯皆不待官府征调便主动披甲请战；","吴起更施励士奇策，特意在军中设下上中下三等酒食飨宴，将从前未曾立功受赏者集中安置在次席，激起这批将士雪耻争先的死战锐气，随即挑选他们编为突击前锋，配以精良重装魏武卒与车骑出城迎敌。","交战之日，求功心切的魏军锐卒奋不顾身，顶着秦军兵力优势直扑秦阵中坚，以严整犀利的步车协同冲垮秦军前锋。秦惠公麾下虽众，却多为仓促征调之师，阵脚一动便连锁溃败，死伤枕藉。吴起一战打断秦人东进脊梁，稳守西河多年，令秦国久久不敢东窥中原。"],"history":"公元前三八九年，秦惠公倾发大军东渡洛水进攻魏国河西重镇阴晋。魏西河郡守吴起平日治军严明、与士卒同甘共苦，奏请魏武侯抽调尚未立功受赏的士卒为骨干，配以战车骑兵鼓行迎击，在阴晋城外以少击众大破秦师，稳固了魏国对河西之地的长期控制。","sources":"吴子·励士；史记·孙子吴起列传；吕氏春秋"},
    "wu_fuchai": {"strategic":["公元前五世纪初，东南吴越两国因疆界交错结下血海深仇。两年前吴王阖闾乘越国丧君举兵南伐，不料在槜李中了越王勾践敢死队排剑自刎乱阵之计，阖闾伤足病亡于归途，临终严命太子夫差勿忘杀父之痛。","夫差继位后立志复仇，每次出入宫庭皆令侍从高声质问是否忘了越王杀父之仇，举国上下在伍子胥督练下整饬舟师步卒，誓要踏平会稽。越王勾践探知吴国备战将成，恃槜李前胜之勇，不顾大夫范蠡力劝守险待机，决意先发制人，尽起越国水师北入太湖讨吴；","夫差闻越军自投罗网，即刻倾发吴国精锐舟师出姑苏迎击，吴越主力会猎于太湖夫椒山。"],"tactical":["太湖水面烟波浩渺，夫椒山孤峙湖中，水师进退全赖风向与阵形严整。勾践率越国舟师抢占夫椒水域列阵，自恃水战娴熟，严阵待攻。夫差先以小股船队试探，见越军阵脚稳固难以强破，便趁入夜北风大作之际施展疑兵之计，分遣翼卫舟楫环绕越军水寨张设火炬、擂鼓呐喊，状若四面合围夜袭。","越军在黑夜中不明虚实，分兵仓皇救应，彻夜惊扰不得安歇，水寨阵线随之松动。待天色破晓，夫差亲擂战鼓，统率养精蓄锐的吴国大翼楼船顺风全线压上，矢石齐发，猛撞越军凌乱船阵。越国水师大溃，舟楫覆没无数，勾践仅携残部退保会稽山顶遣使卑辞请降；","夫差不听伍子胥斩草除根之谏，许越议和称臣，虽一时称雄东南，却留下了日后覆亡的隐患。"],"history":"公元前四九六年吴王阖闾伐越败于槜李伤亡，子夫差继位后命人立庭提示父仇，伍子胥、伯嚭日夜练兵。公元前四九四年春，越王勾践闻吴将伐越，不听范蠡劝阻抢先发水师北上，夫差尽发精锐迎战于太湖夫椒山，乘夜风纵火诈攻扰敌，次日大破越水师，追困勾践于会稽山，迫越称臣入质。","sources":"左传·哀公元年；国语·越语；史记·越王勾践世家"},
    "wu_fuchai@-473": {"strategic":["公元前五世纪前期，曾威震东南与中原的吴王夫差步入穷途末路。早年夫差北赴黄池与晋国争做诸侯盟主之际，卧薪尝胆十余载的越王勾践趁吴都空虚发兵偷袭，击杀留守的吴太子友；","夫差仓皇南归，国中精壮早已在连年远征齐晋中消耗殆尽，数年后笠泽一役再遭越军夜渡击溃，吴国野战精锐至此丧失殆尽。北方齐晋诸侯冷眼旁观，昔日盟友无一发兵南援；","勾践见灭吴时机完全成熟，遂尽发越国水陆大军推进至吴国都城姑苏城外，筑垒断道展开最后围攻，夫差唯有收拢残存军民据守孤城，为吴国社稷作最后一搏。"],"tactical":["姑苏城池水门相通、重垣环抱，夫差依托城防与周边水寨竭力抵御，屡次组织精壮将士开门突击越营，企图撕开缺口打通太湖粮道。然而勾践吸取攻坚教训，严令越军深沟高垒、绝不与困兽硬拼，一面在城外另筑越城紧锁水陆通道，一面坐待姑苏城内积储自行枯竭。","漫长的三年重围之下，姑苏城内生灵涂炭、粮秣断绝，守卒饥疲至极已连弓弦都难以拉开。公元前四七三年隆冬，越军四面猛攻一举攻陷姑苏外内重城，夫差仅带少数近臣杀出重围退据城西南的姑苏山，被迫遣使膝行赴越营哀求仿效当年会稽旧例称臣求和。","勾践不许留国，仅愿迁夫差于甬东养老；夫差仰天长叹无颜在九泉之下面对忠臣伍子胥，遂以帛掩面拔剑自刎，霸业一朝成空。"],"history":"公元前四七五年至前四七三年，吴王夫差因连年北征争霸导致国力耗竭，先后在吴都奇袭战与笠泽之战中惨败于越王勾践，被迫退保都城姑苏。越军筑城断水长围姑苏三年，吴军粮尽援绝，公元前四七三年冬城破，夫差奔上姑苏山遣使乞和遭拒，羞愧掩面自刎而死，吴国灭亡。","sources":"左传·哀公二十二年；史记·吴太伯世家；越绝书"},
    "wu_fuchai@-484": {"strategic":["公元前五世纪前期，吴王夫差自夫椒大破越国、迫使勾践称臣纳质之后，自以为南方隐患已除，一心北上问鼎中原霸主之位，特命开凿邗沟沟通江淮水道以便大军北运。此时北方东方大邦齐国正频频发兵侵凌鲁国，鲁哀公遣使南下联吴抗齐。","老臣伍子胥苦口婆心泣谏夫差，指出齐国于吴不过皮肤之癣，卧榻之侧暗蓄兵力的越国才是心腹大患；夫差听信太宰伯嚭谗言，非但拒纳忠言、借故逼死伍子胥，更于公元前四八四年夏倾发吴国精锐北渡淮泗，会合鲁军深入齐境，与齐国上卿国书统率的齐师主力在泰山以东的艾陵迎头相对。"],"tactical":["艾陵山谷开阔，地扼齐鲁腹地要道，国书自恃齐国兵多车广、本土作战，与高无丕、宗楼分领齐上中下各军列阵迎击；夫差则亲领精锐坐镇吴中军，命胥门巢统上军、王子姑曹统下军严整以待。","晨光初露，两军擂鼓合战，齐上军在公孙夏督率下高唱虞殡战歌死命猛扑，一度击退吴国右翼下军，夺获不少甲盾兵车。然而夫差坐镇中军稳如磐石，亲自擂动战鼓督率久经实战的吴国剑士与大夫展如所部奋勇反击，一举冲穿齐军中坚。吴上军亦趁势合围包抄，齐阵首尾断裂，大败亏输；","主帅国书与高无丕等诸多齐国卿大夫力战阵亡，革车兵甲尽数沦为吴军战利。夫差一战威震北方诸侯，却也使吴国精锐远耗齐鲁，给了南方勾践乘虚而入的可乘之机。"],"history":"公元前四八四年五月，吴王夫差不顾伍子胥先防越国之苦谏，志在北上争霸中原，应鲁哀公之约亲率吴国精锐经邗沟北伐齐国，与齐上卿国书统率的齐军主力决战于艾陵。夫差亲率中军，与胥门巢、展如诸部协同作战，先挫后胜全歼齐中军，阵斩齐帅国书及高无丕等名将，威震齐鲁，但亦加速消耗了吴国国力。","sources":"左传·哀公十一年；史记·吴太伯世家；史记·伍子胥列传"},
    "wu_sunwu": {"strategic":["公元前六世纪末，东南新兴的吴国在吴王阖闾治下重用孙武练兵、伍子胥谋国，国力蒸蒸日上。为消耗体量庞大的宿敌楚国，吴国采纳伍子胥疲楚之策，分兵轮番袭扰楚境，楚军倾巢来救则退，楚军疲惫引还则进，数年间令楚国奔命不暇。","偏巧楚国令尹子常贪婪无度，将前来朝见的蔡昭侯与唐成公长期扣留索贿，致使汉东屏藩蔡、唐两国愤而背楚联吴。公元前五〇六年冬，阖闾与孙武见良机已至，决意发动破楚远征；","吴军主力避开水网密布的江淮常规旧路，溯淮水北上至淮汭舍舟登陆，会合蔡、唐向导悄然穿越大别山险隘，神兵天降般直插楚国汉水腹地。"],"tactical":["柏举位于大别山西麓通往汉水与郢都的门户原野，吴军出山后疾趋汉水东岸，与仓促赶来堵截的楚令尹子常隔水对峙。楚左司马沈尹戌本献良策，请子常凭汉水天险深沟高垒拖住吴军，自己迂回山北焚毁淮汭吴船、堵死山隘以瓮中捉鳖；","岂料子常受小人挑唆，唯恐沈尹戌独吞大功，竟违约强渡汉水主动求战，在小别山至大别山之间连战失利，退屯柏举。交锋当日清晨，阖闾之弟夫概看准子常治军无恩、楚卒皆无斗志，不待王命率先以本部精锐猛冲子常中军；楚阵一触即溃，孙武当即挥动吴军全线压上掩杀，子常弃军奔郑。","吴军乘胜追亡逐北，五战五捷长驱攻入楚都郢城，创下春秋时期攻克大国都城的罕见战绩。"],"history":"公元前五〇六年冬，吴王阖闾以孙武为将、伍子胥与伯嚭辅之，联蔡、唐两国自淮水舍舟登陆，越过大别山奇袭楚国。楚令尹子常即囊瓦率军迎战，沈尹戌建议子常沿汉水正面牵制、自率兵迂回断吴船只后路；子常贪功听谗，渡汉水至小别山、柏举连战皆败，吴军五战五捷攻入楚都郢城。","sources":"左传·定公四年；史记·孙子吴起列传；史记·伍子胥列传"},
    "xibolai_dawei": {"strategic":["公元前十一世纪，定居迦南西南海岸的非利士五城同盟凭借精湛的冶铁技艺与严整步阵，不断向内陆山地扩张，与初建王权的以色列诸支派争战频仍。以色列王扫罗虽屡次统兵抵御，但以色列的兵器甲胄远逊对手，在平原与谷口交锋中每每受制。","非利士诸城再度纠集联军东进，沿通往希伯仑与伯利恒的咽喉谷道深入犹大边境，意图一举压服以色列诸部。扫罗急召各支派男丁赶赴前线迎堵，与非利士大军相遇于梭哥与亚西加之间的以拉谷；年少的大卫奉父命前往军营探视兄长并运送粮饷，恰逢这场关乎以色列国运的对峙陷入僵局。"],"tactical":["以拉谷两侧丘陵夹峙，谷底横亘着布满鹅卵石的干涸溪床，非利士与以色列双方分别据守南北山坡扎营，谁若贸然下谷仰攻敌阵便会陷入被动。","非利士军为打破僵局，派出披挂重型铜甲、手持巨矛的猛士歌利亚每日下谷挑战，企图以阵前单挑摧垮以色列军心，扫罗麾下将士慑于其威，连日无人敢应。大卫进营见状，主动向扫罗请战，他卸下笨重甲胄，仅携牧杖与投石机弦，自溪床拣选光滑石子步入谷底。","歌利亚轻视大卫年少无甲，迈步逼近；大卫趁其尚未及身，疾旋机弦发石，飞石正中歌利亚面门要害，猛士应声扑倒，大卫随即趋前拔其佩刀斩首。非利士全军见勇将暴毙，登时魂飞魄散，弃营西逃，以色列军全线呼喊掩杀，直追至迦特与以革伦城外，大卫自此威名远播。"],"history":"约公元前一〇二五年，沿海非利士五城同盟进军犹大山地边缘，与扫罗统率的以色列军在以拉谷隔谷对峙。非利士巨人勇士歌利亚连日出阵搦战，年轻牧人大卫请缨上阵，弃重甲不用，以机弦甩石击中歌利亚前额将其斩杀，以色列军乘势掩杀非利士军。史料不足：此战仅见于希伯来圣经撒母耳记上，具体年份系后世推算。","sources":"撒母耳记上·第十七章"},
    "xibolai_dawei@-995": {"strategic":["公元前十世纪初，大卫在希伯仑受以色列北方诸支派拥戴，正式合南北为一国，并夺取山地要冲耶路撒冷立为新都。","先前容留过大卫的沿海非利士诸城邦见昔日附庸骤然壮大，唯恐以色列截断内陆商路并反噬海岸平原，遂尽起五城同盟之师东上山地，抢占耶路撒冷西南门户利乏音谷，企图将大卫与南方犹大腹地拦腰隔断。王国初立根基未稳，一旦谷道失守则新都危殆；","大卫当即收拢以色列精壮勇士退据山寨整备，旋即亲率大军出山迎向利乏音谷，誓要挫败非利士人的合围图谋。"],"tactical":["利乏音谷地处耶路撒冷西南山地走廊，谷地宽敞，两侧山坡遍生桑林，非利士联军在谷中广布营阵，依仗优势铁器步卒封锁大道。大卫先率以色列勇士自高处顺势猛冲敌营，如急流决堤般正面击穿非利士战线，缴获敌军遗弃的神像；非利士人不甘败绩，旋即重整大军再度填满山谷。","二次交锋之际，大卫不再正面强攻，而是借谷边桑林掩护悄然率部迂回至敌阵后背，静候山风吹动树梢枝叶作响以掩盖脚步声，突然自侧后方发起雷霆奇袭。非利士大军首尾不能相顾，阵脚彻底崩溃，大卫率军一路追击至基色城外，自此一举扭转双方攻守大势，奠定以色列联合王国的强盛基业。"],"history":"约公元前九九五年，大卫受膏统合以色列南北诸支派并定都耶路撒冷，沿海非利士五城深感威胁，两度大举出兵屯驻耶路撒冷西南的利乏音谷企图扼杀新王国。大卫先在巴力毗拉心正面冲决敌阵，复在第二次会战中绕至桑林背后奇袭大破非利士军，彻底解除非利士对以色列山地的压制。史料不足：年份系依圣经年代推算，非利士统帅名氏失载。","sources":"撒母耳记下·第五章；历代志上·第十四章"},
    "yashu_saergong": {"strategic":["公元前八世纪后期，盘踞亚美尼亚高原的乌拉尔图王国与新亚述帝国南北争锋已历数代。乌拉尔图国王鲁萨一世倚仗崇山峻岭之险，频频向扎格罗斯山脉渗透，扶植曼努亚与米底边境诸侯背叛亚述，令亚述北疆岁无宁日。","萨尔贡登基平定国内叛乱后，深知若不摧毁乌拉尔图在高原上的霸权，亚述便无法安心经略两河与西方。公元前七一四年夏，萨尔贡亲率亚述大军自卡拉赫启程，展开在位第八次远征，先入曼努亚稳定盟邦，继而取道险峻山隘深入乌拉尔图腹地；","鲁萨一世亦集结高原劲旅与山岳盟军赶赴前线阻截，一场围绕北方高原霸权的决战迫在眉睫。"],"tactical":["乌拉尔图全境高山深谷交错，道路崎岖难行，鲁萨一世率大军进驻白雪覆顶的险峰山谷之间，欲趁亚述军翻山越岭、人困马乏之际以逸待劳。不料萨尔贡虽经长途跋涉，却不等全军休整列阵，亲率精锐近卫骑队与战车迎着山地阵线悍然发动突击。","亚述铁骑凶猛穿插，一举凿穿乌拉尔图军中坚，鲁萨一世的护卫溃散，本人仅得换乘牝马狼狈逃离战场。萨尔贡乘胜横扫乌拉尔图富庶平原与凡湖周边堡寨，迫近都城图什帕方向；","见高原都城险固难急下，萨尔贡于回师途中仅携轻骑翻越密林绝岭，出其不意攻陷乌拉尔图王室加冕圣城穆萨西尔，将哈尔迪神庙的青铜礼器与金银席卷一空。鲁萨一世闻圣城陷落悲愤自尽，乌拉尔图自此一蹶不振。"],"history":"公元前七一四年，亚述王萨尔贡发动在位第八次远征，翻越扎格罗斯山脉讨伐北方劲敌乌拉尔图国王鲁萨一世。萨尔贡在瓦乌什山突袭大败鲁萨一世主力，蹂躏乌拉尔图富庶谷地、逼近都城图什帕一带，回师途中奇袭攻陷乌拉尔图宗教圣城穆萨西尔，掳掠哈尔迪神庙巨额珍宝，鲁萨一世闻讯自尽。","sources":"萨尔贡二世致阿舒尔神书信；亚述王家铭文"},
    "yashu_saergong@-710": {"strategic":["公元前八世纪末，亚述王萨尔贡先后荡平西方叙利亚叛盟与北方劲敌乌拉尔图，唯独帝国南方的巴比伦尼亚仍悬于版图之外。早在十余年前亚述宫廷易主之际，迦勒底首领米罗达巴拉旦便依仗东方埃兰的武力撑腰入主巴比伦，自称巴比伦国王，拉拢两河下游各游牧部族抗拒亚述王命。","萨尔贡隐忍多年，直至四方边患悉数扫清，方于公元前七一〇年倾发主力大举南征；他吸取早年正面受阻埃兰的教训，并未直接强攻巴比伦北关，而是沿底格里斯河东岸迂回南插，先行击破沿途阿拉姆部族并切断埃兰西援通道，从东南方向反包抄直逼巴比伦城。"],"tactical":["巴比伦城垣宏伟，河渠交错，米罗达巴拉旦原先指望埃兰盟军自东侧夹击亚述远征军，见萨尔贡先行封死东方边界、埃兰王慑于兵威按兵不动，城内守军顿时陷入孤立。加之米罗达巴拉旦连年征敛军费，早已引发巴比伦神庙祭司与豪门望族的不满。","萨尔贡屯驻于杜尔拉丁尼步步紧逼，分兵肃清城外迦勒底各营垒，对巴比伦形成合围之势。米罗达巴拉旦自知困守孤城必成瓮中之鳖，趁夜率亲信弃城南逃海泽故地；城中祭司与贵族随即大开城门，恭迎萨尔贡入驻巴比伦。","萨尔贡在新年庆典上亲执马尔杜克神像之手正式加冕为巴比伦王，开凿运河、优礼神庙，使南北两河重新归于亚述一统。"],"history":"公元前七二二年萨尔贡即位之初，迦勒底比特雅金部族首领马尔杜克阿普拉伊丁那二世即圣经所载米罗达巴拉旦联合埃兰自立为巴比伦王，割据南方十余年。公元前七一〇年，已彻底平定北方乌拉尔图与西方叙利亚的萨尔贡举兵南征，先切断埃兰援道，逼走米罗达巴拉旦，在祭司与市民迎奉下进占巴比伦城并兼领巴比伦王号。","sources":"萨尔贡二世年代记；巴比伦编年史"},
    "yashu_saergong@-720": {"strategic":["公元前八世纪后期，萨尔贡初登亚述王位，国内贵族异议未平，南方巴比伦与东方埃兰又趁势发难，令亚述王师一时无暇西顾。","叙利亚中部的哈马特首领伊卢比迪以为亚述霸权即将瓦解，当即自立为王，串联大马士革、阿帕德、西米拉及撒马利亚故地诸城公开拒纳贡赋，组建起声势浩大的黎凡特反叛同盟，并向南方埃及暗求外援。一旦叙利亚走廊失控，亚述通往地中海的赋税与商道便将彻底断绝；","萨尔贡稳住两河防线后不敢有丝毫迁延，于公元前七二〇年亲统亚述常备军团渡过幼发拉底河，直扑伊卢比迪集结重兵的奥龙特斯河要冲卡尔卡尔。"],"tactical":["卡尔卡尔扼守奥龙特斯河中游渡口与南北官道，伊卢比迪纠集叙利亚诸城步骑与战车依托河岸及城寨列阵，妄图重演昔日诸邦合兵阻遏亚述之局。","萨尔贡深知叛军虽众而各怀异心，抵达战场后毫不迟疑，以亚述重装战车与长矛步阵正面强压联军中路，同时遣精锐骑队自侧翼高速迂回包抄河岸退路。面对久经战阵的亚述职业军团，各城拼凑而成的叛军防线很快在猛烈冲击下支离破碎，士卒争相溃逃入城。","萨尔贡乘胜督军强攻攻陷卡尔卡尔并付之一炬，生擒叛盟魁首伊卢比迪严惩示众，随后挥师南下在拉菲亚击退埃及援兵，将哈马特彻底改置为亚述行省，黎凡特诸城自此再不敢轻言叛乱。"],"history":"公元前七二〇年，亚述王萨尔贡平定国内动荡并应对东方埃兰挑战之际，哈马特首领伊卢比迪串联阿帕德、西米拉、大马士革及撒马利亚残余势力结成叙利亚反亚述同盟，陈兵奥龙特斯河畔重镇卡尔卡尔。萨尔贡亲率亚述大军疾驰西征，在卡尔卡尔野战中击溃联军，攻克城池并生擒处死伊卢比迪，继而南下击败埃及援军，稳固了亚述对整个黎凡特的统治。","sources":"萨尔贡二世王家年表铭文；杜尔舍鲁金碑铭"},
    "yue_goujian": {"strategic":["公元前五世纪前期，越王勾践自吴国赦归会稽后，悬胆于坐、身自耕作，重用文种治国富民、范蠡整军练卒，一面卑辞厚礼麻痹吴王夫差并借粮构陷忠臣伍子胥致死，一面暗蓄雷霆一击之力。反观夫差志得意满，连年兴师北伐齐鲁、远赴黄池与晋争霸，国内精壮凋敝、仓廪空虚。","勾践先趁夫差北会诸侯之机奇袭吴都掳杀吴太子，数年后又在笠泽夜渡夹击，彻底打垮吴国野战主力。至公元前四七五年，吴国羽翼尽折、外无诸侯来援，勾践决意彻底了结两国世代宿怨，倾发越国水陆劲旅北上，将夫差最后的立足之地吴都姑苏团团围困。"],"tactical":["姑苏城池河渎纵横、城郭宏阔，夫差收拢残存守卒凭水陆重关死守，指望耗尽越军锐气。勾践深知困兽犹斗不可急攻，遂采纳稳扎稳打之策，在姑苏城外修筑坚垒，截断太湖与江淮通往城内的全部水道粮路，以长围久困消磨吴国最后元气。","围城历时三载，吴军数度出城突围皆被越军严阵击回，城中粮食告罄，饿殍满路，再无交锋之力。公元前四七三年冬，勾践发起总攻突破姑苏城防，夫差仅携亲随突围奔上城西南的姑苏山，派使臣肉袒膝行赴越营乞和，哀求如当年会稽旧事般留存吴国宗祀。","范蠡挺身厉谏天予不取反受其咎，勾践遂仅许安置夫差于甬东孤岛；夫差羞愤绝望，掩面拔剑自刎，吴国灭亡，勾践随后北渡淮水会盟诸侯，威震东南。"],"history":"越王勾践夫椒兵败归国后卧薪尝胆、十年生聚十年教训，乘吴王夫差北上黄池争霸之机于公元前四八二年袭破吴都，公元前四七八年笠泽之战再破吴军主力，继而自公元前四七五年起大举围困吴都姑苏。经三年长期围困，公元前四七三年冬越军攻破姑苏，夫差退保姑苏山求和不允自刎而死，吴国灭亡。","sources":"左传·哀公二十二年；国语·越语；史记·越王勾践世家"},
    "yue_goujian@-478": {"strategic":["公元前四七八年，距离越王勾践归国卧薪尝胆已逾十余载，吴越国势早已发生根本逆转。越国经文种与范蠡多年休养生息，仓廪丰实，士卒人人思奋雪耻；反观吴王夫差先在北方艾陵与黄池耗尽国中精壮，国内又遭逢大旱饥荒，不得不饮鸩止渴向越国借取蒸熟稻种，致使田亩绝收、民怨沸腾。","勾践与范蠡审时度势，断定摧毁吴国脊梁的决战时刻已到，遂尽起越国水陆劲旅北上讨吴；夫差闻警大惊，搜刮国内尚能执戈的军民倾城南出，抢在越军逼近姑苏之前进驻太湖东出的笠泽北岸，妄图凭江水天险挡住勾践北进。"],"tactical":["笠泽江面宽阔，水流湍急，吴王夫差沿北岸连营布防，越王勾践屯军南岸，两军隔水相望。白昼正面强渡必遭岸上半渡而击，勾践遂于入夜之后布下疑兵奇局，分派左右两翼偏师溯流与顺流拉开距离，在夜色掩护下同时擂动战鼓、高声呐喊渡水，装作越军主力分自上下游两翼强渡包抄。","夫差在黑夜中听闻两侧鼓声震天，大惊失色，急忙将自己坐镇的中军一分为二，火速派往左右两翼增援堵截。勾践在南岸静听吴营调动嘈杂，算定夫差中军已然空虚，当即亲率口衔木枚、偃旗息鼓的越国君子私卒悄然涉水横渡中流，登岸后方才齐声发喊猛扑吴王大营。","吴中军猝不及防顷刻溃散，左右两翼闻中枢已失亦相继崩盘；越军连战皆捷直追至姑苏城郊，一战打断吴国最后脊梁。"],"history":"公元前四七八年三月，越王勾践乘吴国连年北征及旱灾饥荒之机大举伐吴，吴王夫差尽发残余主力南下，在吴都以南的笠泽即松江一带隔江设防。勾践采纳声东击西之计，入夜命左右两翼鸣鼓喧嚣吸引吴军分兵，自率精锐私卒衔枚潜渡中流突袭夫差中军，三战三捷彻底歼灭吴国野战主力，奠定灭吴大局。","sources":"左传·哀公十七年；国语·吴语；史记·越王勾践世家"},
    "yue_goujian@-496": {"strategic":["公元前五世纪初，吴国自攻破楚都郢城之后兵威冠于东南，唯独南邻越国屡趁吴军远征之际袭扰后方，两国积怨日深。公元前四九六年，久掌越国权柄的越王允常病逝，年轻的勾践刚刚嗣位，国内人心未固、诸部尚待安抚。","雄才大略却年迈骄矜的吴王阖闾闻听越国丧君，以为正是兼并越地的天赐良机，不顾邻国居丧不伐之古礼，亲统久经沙场的吴国劲旅浩浩荡荡南下压境。面对久战余威的强吴大军，初登王位的勾践毫无惧色，火速集结越国敢死锐士北上迎敌，与阖闾主力对峙于吴越边境的水乡重镇槜李。"],"tactical":["槜李一带河港交错、田畴平衍，吴王阖闾治军素来严整，吴军披坚执锐结成铜墙铁壁般的方阵，越王勾践先遣精锐试探冲锋数次，皆被吴阵纹丝不动地挡回。见寻常战法断难撼动强敌，勾践当机立断施展骇人奇谋，从军中挑出犯有死罪的囚徒编成数排，令他们赤膊持剑缓步走到吴军阵前；","在阖闾与吴军将士疑惑注视之下，这批敢死罪徒齐声高呼不负君恩，竟然当众排成队列挥剑自刎。吴军上下从未见过如此惨烈诡异之景，前排士卒纷纷伸颈惊愕张望，严整肃穆的阵线瞬间出现松动。勾践看准电光石火的破绽，擂鼓挥动潜伏待命的越国主力狂飙突进，一举冲垮失神的吴军大阵；","混战中越大夫灵姑浮挥戈斩落阖闾战靴并重创其足趾，吴师大败北撤，阖闾伤重崩于半途，吴越世代死仇由此彻底点燃。"],"history":"公元前四九六年夏，越王允常去世，少子勾践初立，曾破楚入郢的吴王阖闾趁越国国丧亲率精兵南下伐越，两军在嘉兴西南的槜李对阵。勾践见吴军阵法森严难撼，采纳奇计遣死罪士卒分列阵前高呼自刭，趁吴军将士错愕观望之际全军突击，大败吴师，大夫灵姑浮以戈击伤阖闾脚趾，阖闾旋即病死归途。","sources":"左传·定公十四年；史记·越王勾践世家"},
    "zhou_jifa": {"strategic":["公元前十一世纪中叶，统治中原已久的殷商王朝渐入暮年，商王子受刚愎自用，重用酷吏，大兴土木，致使贵族离心、庶民怨怼；加之商廷主力长年陷于东南淮夷战事，王畿防务空虚。而在西方渭水流域，周族经文王姬昌累年经营，剪灭崇、密诸邦，迁都丰邑，西方诸侯多归附于周。","姬发继位后，先率师东观兵于孟津以试探诸侯向背，见时机尚未完全成熟便暂且敛兵待变。及至商廷内乱加剧、太师疵与少师强抱乐器奔周，姬发决意兴兵伐商，遍告诸侯，会合庸、蜀、羌、微、卢、彭、濮等西南各方国部族，自孟津冒雨东渡黄河，昼夜兼程直扑商都朝歌南郊的牧野。"],"tactical":["朝歌以南的牧野地势平坦开阔，极利战车驰骋列阵。子受闻报周联军渡河逼近，来不及召回远在东南的精锐主力，只得仓促将王都周边的战俘与罪隶编伍授兵，倾城出屯牧野迎战。天明时分，姬发于阵前宣誓勖勉，严令诸军步伐整齐、勿贪杀降，随即命太公望率精锐战车与虎贲猛士率先冲阵。","周军车步协同、攻势凌厉，而商军前阵士卒本就怨恨子受暴政，交锋未久便纷纷掉转戈矛，反过来为周军引路冲杀商廷本阵。商军阵脚顷刻大乱，后队溃散奔逃，子受见大势已去，策马退回朝歌，登上鹿台引火自焚。商祚就此终结，姬发入主中原，分封诸侯、确立宗法，开启了周代天下格局。"],"history":"约公元前一〇四六年，周武王姬发乘商王帝辛即子受连年征伐东夷、国内空虚怨叛之机，率西岐周军东出孟津，会合庸、蜀、羌、髳、微、卢、彭、濮诸方国联军，于商都朝歌南郊牧野决战。商军临时武装的奴隶与战俘临阵倒戈，周军乘势击溃商师，子受退登鹿台自焚，商朝灭亡，西周建立。异说：武王克商之年另有前一〇二七年、前一〇四五年诸说。","sources":"尚书·牧誓；史记·周本纪；利簋铭文"},
};
